# Raw Objects for unreadable media store a short provenance descriptor such as
# ``[document: a.pdf; type=application/pdf; size=…]`` or ``[photo: …]``.  That is
# not extracted file text and must never become synthesis evidence.
_FILE_PROVENANCE_STUB = re.compile(
    r"\A\s*\[[A-Za-z][A-Za-z0-9_-]{0,40}:\s*",
    re.ASCII,
)


def _is_file_provenance_stub(text: str) -> bool:
    """Whether stored raw_content is only an upload descriptor, not file text."""

    return bool(_FILE_PROVENANCE_STUB.search(str(text or "")))


def _mime_is_visual_without_text_layer(mime_type: str, *, extraction_chars: int = 0) -> bool:
    """Image/photo always; PDF with zero extractable chars is a scan for our stack."""

    mime = str(mime_type or "").casefold()
    if mime.startswith("image/"):
        return True
    return mime == "application/pdf" and extraction_chars <= 0


def _refusal_classification_text(answer: str) -> str:
    return " ".join(_leading_model_assertion(str(answer or "")).split())


def _is_false_readable_attachment_refusal(answer: str) -> bool:
    """Whether a model answer falsely denies access to an already-parsed file.

    Source truth belongs to the parser: when coverage is complete and readable
    evidence exists, the model may struggle with a field, but it may not claim
    the whole file is missing or demand a reupload.  Detection is multi-signal
    (file noun + access denial, or any reupload request for the file) so natural
    paraphrases cannot walk around a single brittle phrase list.
    """

    text = _refusal_classification_text(answer)
    if not text:
        return False
    # Pure field-level uncertainty is truthful and must not become a whole-file
    # recovery loop.  A reupload demand still overrides this carve-out.
    field_level = bool(
        re.search(
            r"(?:"
            r"\bне\s+(?:могу|удалось|получается)\s+"
            r"(?:разобрать|разглядеть|прочитать|распознать)\s+"
            r"(?:одн\w+\s+)?(?:цифр\w*|символ\w*|букв\w*|знак\w*|пол[ея]\w*|строк\w*)\b|"
            r"\b(?:одн\w+\s+)?(?:цифр\w*|символ\w*)\s+в\s+строк\w*\b|"
            r"\bнечётк\w*\s+(?:цифр\w*|пол[ея]\w*|строк\w*)\b"
            r")",
            text,
            re.IGNORECASE,
        )
    )
    asks_reupload = bool(_FALSE_READABLE_REUPLOAD.search(text))
    denies_access = bool(_FALSE_READABLE_ACCESS_DENIAL.search(text))
    mentions_file = bool(_FALSE_READABLE_FILE_NOUN.search(text))
    deictic_file = bool(re.search(r"\b(?:его|её|их|это|этот|ваш)\b", text, re.IGNORECASE))
    if (
        field_level
        and not asks_reupload
        and not re.search(
            r"\b(?:весь|целиком|полностью)\b",
            text,
            re.IGNORECASE,
        )
    ):
        return False
    if asks_reupload and (mentions_file or denies_access or deictic_file):
        return True
    return bool(denies_access and (mentions_file or deictic_file))


def _capability_refusal_match(answer: str) -> re.Match[str] | None:
    text = _refusal_classification_text(answer)
    if (
        not text
        or re.search(r"\bне\s+могу\s+не\s+\w", text, re.IGNORECASE)
        or (
            text.rstrip().endswith("?")
            and (
                re.match(
                    r"^(?:почему|разве|неужели|могу\s+ли|можно\s+ли)\b",
                    text,
                    re.IGNORECASE,
                )
                or re.match(
                    r"^(?:этого|это)\s+я\b[^.!?\n]*\bне\s+могу\b",
                    text,
                    re.IGNORECASE,
                )
            )
        )
    ):
        return None
    cursor = 0
    while cursor < len(text):
        refusal = _CAPABILITY_REFUSAL.search(text, cursor)
        if refusal is None:
            return None
        uncertainty = _UNCERTAINTY_NOT_REFUSAL.search(text, cursor)
        if (
            uncertainty is not None
            and uncertainty.start() <= refusal.end()
            and uncertainty.end() > refusal.start()
        ):
            # The uncertainty owns only its own span. Search again after it: a
            # later real capability refusal in the same sentence still needs a
            # useful next step.
            cursor = max(uncertainty.end(), cursor + 1)
            continue
        return refusal
    return None


def refusal_lacks_useful_alternative(answer: str) -> bool:
    text = _refusal_classification_text(answer)
    refusal = _capability_refusal_match(text)
    if refusal is None:
        return False
    tail = _IMPOSSIBLE_OUTSIDE_ALTERNATIVE.sub("", text[refusal.end() :])
    return not _USEFUL_NEXT_STEP.search(tail)


def add_useful_refusal_alternative(answer: str) -> str:
    text = str(answer or "").strip()
    if not refusal_lacks_useful_alternative(text):
        return text
    return f"{text}\n\n{_REFUSAL_ALTERNATIVE}"


def _model_endpoint_is_private(settings: Any) -> bool:
    """A second copy of a private draft may go only to the local model path."""

    host = urllib.parse.urlsplit(str(getattr(settings, "llm_base_url", "") or "")).hostname or ""
    if host in {"localhost"}:
        return True
    try:
        address = ipaddress.ip_address(host)
    except ValueError:
        return False
    return address.is_private or address.is_loopback


def _self_description(settings: Any, *, served_name: str = "") -> str:
    """Что Пятница на самом деле такое — из настроек, а не из памяти модели.

    ГРАНИЦА ПРАВДЫ здесь не менее важна, чем сама правда. Имя модели и адрес
    эндпойнта система знает точно; модели видеокарты в настройках нет. Подставить
    вместо чужой выдумки свою — не лечение: замеренная беда была не в том, что
    названы неверные карты, а в том, что названы карты, которых никто не знает.

    Имя берётся у самого эндпойнта, а не из `llm_model`: там стоит «dispatcher» —
    псевдоним маршрутизатора, человеку он не говорит ничего.
    """
    name = (served_name or "").strip() or str(getattr(settings, "llm_model", "") or "").strip()
    base = str(getattr(settings, "llm_base_url", "") or "")
    host = urllib.parse.urlsplit(base).hostname or ""
    private = False
    if host:
        try:
            private = ipaddress.ip_address(host).is_private or ipaddress.ip_address(host).is_loopback
        except ValueError:
            private = host in {"localhost"}
    where = (
        "Работаю на твоём железе: сервер модели стоит в локальной сети, наружу твои данные "
        "за ответом не уходят."
        if private
        else f"Сервер модели указан по адресу {base or 'не задан'}."
    )
    return (
        f"Моё ядро — языковая модель «{name or 'не указана в настройках'}», её обслуживает "
        f"локальный сервер. {where}\n\n"
        "Какая именно видеокарта под этим стоит, я не знаю — в моих настройках этого нет, и "
        "выдумывать не буду."
    )


def _is_household_turn(context: Any) -> bool:
    """Разговорная реплика: «как дела», «устал сегодня», «о чём поговорим».

    Два признака вместо одного, и оба нужны. Закрытый список (`small_talk`) ловит
    «привет» и «спасибо», но молчит на «да вот думаю, о чём с тобой поговорить»;
    вердикт «быт» ловит понимание, но на самой короткой реплике арбитр видов не
    зовётся вовсе, и вердикта нет. Асимметрия уже стоила одного дефекта: реплика
    из списка не получала инструментов, а распознанная пониманием получала весь
    набор.
    """
    if getattr(context, "small_talk", False):
        return True
    kind = str((getattr(context, "outward_verdict", None) or ("", None))[0] or "")
    return kind.startswith("быт")


def _archive_is_weak(hits: list[dict[str, Any]]) -> bool:
    """Отвечает ли архив уверенно — или просто что-то нашёл.

    Возвращает False (то есть «архив силён»), когда оценки переранжировщика нет
    вовсе: сервис бывает выключен или недоступен, и его отказ не должен открывать
    дорогу наружу. Тогда действует прежнее правило «нашлось — значит про своё».
    """
    scored = [item.get("_rerank_score") for item in hits]
    known = [float(score) for score in scored if score is not None]
    if not known:
        return False
    return max(known) < _ARCHIVE_IS_SURE


#: Просьба поставить напоминание. Наружу такое не уходит НИКОГДА.
#:
#: Замерено на недельном прогоне 2026-08-02: «Напомни мне в среду созвон с
#: подрядчиком» ушло в поисковик строкой «созвон с подрядчиком среда» — арбитр
#: счёл это вопросом о внешнем мире. Цена двойная: напоминание не поставлено, а
#: дело человека вместе с днём недели ушло в чужой поисковик.
#:
#: Здесь решает структура, а не модель: если человек просит не забыть — это
#: просьба к помощнику, и обсуждать нечего.
#: «Что писал JBL?», «чем занимался Пегас», «что скидывал Иванов» — вопрос о
#: деятельности ЧЕЛОВЕКА, а не о содержимом архива.
#:
#: Найдено владельцем 2026-08-03 на живой переписке. У Пятницы есть отдельный
#: инструмент `user_activity` («что один аккаунт писал и загружал, по имени,
#: которым человек пользуется»), но модель его не позвала: «что писал JBL?»
#: ушло в поиск по архиву и вернулось «похожее есть, но не по делу». Владелец
#: объяснил прямым текстом — «JBL это пользователь, как и Пегас», — и следующий
#: вопрос «Что писал Пегас?» получил ровно тот же ответ.
#:
#: Уговаривать модель бесполезно: это уже известно про веб-поиск и про голос —
#: лечится ТОЛЬКО выполнением до её хода.
_ASKS_WHAT_A_PERSON_WROTE = re.compile(
    r"(?:^|\W)(?:"
    r"(?:что|чего|о\s+чём)\s+(?:\w+\s+){0,2}?(?:писал\w*|пишет|скидывал\w*|скинул\w*|"
    r"присылал\w*|прислал\w*|загружал\w*|загрузил\w*|говорил\w*|спрашивал\w*|делал\w*)"
    r"|чем\s+(?:\w+\s+){0,2}?(?:занимал\w*|занят\w*)"
    r"|активность\s+\w+"
    r")",
    re.IGNORECASE,
)

# Exact cross-account document inventory.  This is deliberately narrower than
# the general "what did a person do" route: all three parts must be present — an
# inventory request, a file/document subject, and an upload verb.  The account
# and temporal scope are then resolved by code: one explicit closed day, or an
# unqualified all-time snapshot.  An open/ambiguous temporal cue is never
# widened to all time.
_PERSON_DOCUMENT_INVENTORY_ACTION = re.compile(
    r"\b(?:какие|покаж\w*|перечисл\w*|назов\w*|спис\w*|вс[еёхя]|сколько)\b",
    re.IGNORECASE,
)
_PERSON_DOCUMENT_INVENTORY_SUBJECT = re.compile(
    r"\b(?:документы|документов|файлы|файлов|вложения|вложений|материалы|материалов)\b",
    re.IGNORECASE,
)
_PERSON_DOCUMENT_INVENTORY_UPLOAD = re.compile(
    r"\b(?:загруз|загруж|присыл|присла|отправ|скид|прикреп|добав)\w*\b",
    re.IGNORECASE,
)
_PERSON_DOCUMENT_INVENTORY_PROHIBITED_INFINITIVE = (
    r"(?:показывать|перечислять|называть|выводить|искать|находить|проверять)"
)
_NEGATED_PERSON_DOCUMENT_INVENTORY_ACTION = re.compile(
    rf"\b(?:"
    # A direct negative imperative is authority.  Indicative descriptions such
    # as ``ты не показывал`` and ``почему ты не показываешь`` deliberately do
    # not share this ending grammar.
    r"не\s+(?:покаж(?:и|ите)|показыва(?:й|йте)|перечисл(?:и|ите)|"
    r"перечисля(?:й|йте)|назов(?:и|ите)|называ(?:й|йте)|вывод(?:и|ите)|"
    r"ищ(?:и|ите)|наход(?:и|ите)|проверя(?:й|йте))\b|"
    # Modal/remembered commands may use an infinitive, but the bounded host is
    # mandatory so an arbitrary report about somebody not showing files is not
    # reinterpreted as the user's current prohibition.
    rf"(?:(?:я\s+)?прошу|я\s+просил(?:а|и)?|мож(?:ешь|ете)|лучше|пожалуйста)"
    rf"\s+(?:меня\s+|мне\s+|нам\s+|тебя\s+){{0,2}}не\s+"
    rf"{_PERSON_DOCUMENT_INVENTORY_PROHIBITED_INFINITIVE}\b|"
    rf"не\s+(?:надо|нужно|следует)\s+"
    rf"(?:(?:мне|нам|сейчас|пока|больше|здесь)\s+){{0,3}}"
    rf"{_PERSON_DOCUMENT_INVENTORY_PROHIBITED_INFINITIVE}\b|"
    rf"(?:я\s+)?не\s+хочу\s+(?:(?:сейчас|пока|больше)\s+){{0,2}}"
    rf"(?:видеть|получать|смотреть)\b|"
    rf"(?:я\s+)?не\s+хочу\s*,?\s+чтобы\s+"
    rf"(?:(?:ты|вы|мне|нам)\s+){{1,2}}"
    r"(?:показыва|перечисля|называ|выводи|иска|находи|проверя)\w*\b|"
    rf"давай(?:те)?\s+не\s+буд(?:ем|ь|ьте)\s+"
    rf"{_PERSON_DOCUMENT_INVENTORY_PROHIBITED_INFINITIVE}\b"
    rf")",
    re.IGNORECASE,
)
_PERSON_DOCUMENT_INVENTORY_NEGATED_MENTION = re.compile(
    r"\bне\s+(?:(?:надо|нужно|следует|буд(?:ем|у|ешь|ете|ут))\s+)?"
    r"(?:(?:мне|нам|сейчас|пока|больше|здесь|ещ[её])\s+){0,3}"
    r"(?:показыва|покаж|перечисл|назов|называ|вывед|выводи|ищ|иска|найд|"
    r"находи|провер)\w*\b",
    re.IGNORECASE,
)
_PERSON_DOCUMENT_INVENTORY_META_QUESTION_PREFIX = re.compile(
    r"(?:^|\s)(?:почему|зачем|разве|правда\s+ли|кто\s+сказал|ты\s+правда)\b",
    re.IGNORECASE,
)
_NEGATED_PERSON_DOCUMENT_INVENTORY_ACK = "Хорошо, не буду показывать, перечислять или искать эти файлы."

# Colloquial first-person inventory with an exact calendar day.  The ordinary
# inventory recogniser deliberately requires an explicit file noun; real chat
# often omits it in the closed form ``14 числа что я загружал?``.  Keep this
# exception as a full-match grammar so neighbouring activity/message questions
# cannot be promoted to a files-only system read.
_PERSON_DOCUMENT_COMPACT_SELF_UPLOAD = re.compile(
    r"\s*(?:а\s+)?(?:"
    r"(?:[1-9]|[12]\d|3[01])(?:-?(?:го|е))?\s+числ(?:а|о|е)\s+"
    r"(?:что|чего)\s+я\s+"
    r"(?:загружал(?:а)?|загрузил(?:а)?|присылал(?:а)?|прислал(?:а)?|"
    r"отправлял(?:а)?|отправил(?:а)?|скидывал(?:а)?|скинул(?:а)?|"
    r"прикреплял(?:а)?|прикрепил(?:а)?)"
    r"|(?:что|чего)\s+я\s+"
    r"(?:загружал(?:а)?|загрузил(?:а)?|присылал(?:а)?|прислал(?:а)?|"
    r"отправлял(?:а)?|отправил(?:а)?|скидывал(?:а)?|скинул(?:а)?|"
    r"прикреплял(?:а)?|прикрепил(?:а)?)"
    r"\s+(?:[1-9]|[12]\d|3[01])(?:-?(?:го|е))?\s+числ(?:а|о|е)"
    r")"
    r"\s*[?!.]*\s*",
    re.IGNORECASE,
)


def _person_document_inventory_request(message: str) -> bool:
    """Linear equivalent of the three-lookahead inventory recogniser."""

    command = _QUOTED_TEXT.sub(" ", _record_source_command_text(message))
    if _negated_person_document_inventory_request(
        message
    ) or _PERSON_DOCUMENT_INVENTORY_NEGATED_MENTION.search(command):
        return False
    return bool(
        _PERSON_DOCUMENT_COMPACT_SELF_UPLOAD.fullmatch(command)
        or (
            _PERSON_DOCUMENT_INVENTORY_ACTION.search(command)
            and _PERSON_DOCUMENT_INVENTORY_SUBJECT.search(command)
            and _PERSON_DOCUMENT_INVENTORY_UPLOAD.search(command)
        )
    )


def _negated_person_document_inventory_request(message: str) -> bool:
    """A direct prohibition is a closed no-read command, never an inventory."""

    command = _QUOTED_TEXT.sub(" ", _record_source_command_text(message))
    action = _NEGATED_PERSON_DOCUMENT_INVENTORY_ACTION.search(command)
    if action is None:
        return False
    if command.rstrip().endswith("?") and _PERSON_DOCUMENT_INVENTORY_META_QUESTION_PREFIX.search(
        command[: action.start()]
    ):
        return False
    return bool(
        command
        and _PERSON_DOCUMENT_INVENTORY_SUBJECT.search(command)
        and _PERSON_DOCUMENT_INVENTORY_UPLOAD.search(command)
    )


_PERSON_DOCUMENT_INVENTORY_REMAINDER_BOUNDARY = re.compile(
    r"(?P<separator>"
    r"\?\s*(?:а\s+)?(?:(?:потом|затем)\s+)?|"
    r"[,;:]\s*(?:а\s+)?(?:(?:потом|затем)\s+)?(?:и\s+)?|"
    r"\s+(?:а\s+)?(?:потом|затем)\s+|"
    r"\s+и\s+"
    r")(?P<remainder>[^\r\n]{1,300})$",
    re.IGNORECASE,
)
_PERSON_DOCUMENT_INVENTORY_WEATHER_REMAINDER = re.compile(
    r"\b(?:погод|прогноз|температур|weather|forecast|temperature)\w*\b",
    re.IGNORECASE,
)


def _person_document_inventory_remainder(message: str) -> _LocateClauseDecomposition:
    """Split one exact inventory from an independently actionable suffix."""

    surface = str(message or "").strip()
    if not surface or len(surface) > 1_000:
        return _LocateClauseDecomposition(surface)
    masked, literals_closed = _masked_locate_literals(surface)
    if not literals_closed:
        return _LocateClauseDecomposition(surface, remainder_known=False)
    for matched in _PERSON_DOCUMENT_INVENTORY_REMAINDER_BOUNDARY.finditer(masked):
        clause = surface[: matched.start("separator")].rstrip(" \t,;:?!")
        remainder = surface[matched.start("remainder") :].strip()
        if (
            clause
            and remainder
            and _person_document_inventory_request(clause)
            and _PERSON_DOCUMENT_INVENTORY_WEATHER_REMAINDER.search(_record_source_command_text(remainder))
        ):
            return _LocateClauseDecomposition(
                locate_clause=clause,
                open_remainder=remainder,
                remainder_known=True,
                split=True,
            )
        if (
            clause
            and remainder
            and _PERSON_DOCUMENT_INVENTORY_WEATHER_REMAINDER.search(_record_source_command_text(clause))
            and _person_document_inventory_request(remainder)
        ):
            # Composition order does not grant either clause ownership over the
            # other.  Normalize weather-first wording to the same two sealed
            # lanes as inventory-first: the private catalog is settled locally,
            # while only the weather clause reaches weather policy.
            return _LocateClauseDecomposition(
                locate_clause=remainder,
                open_remainder=clause,
                remainder_known=True,
                split=True,
            )
    return _LocateClauseDecomposition(surface)


class _PersonDocumentInventoryCompatibility:
    """Keep the legacy ``.search`` seam without restoring its regex sink."""

    @staticmethod
    def search(message: str) -> re.Match[str] | None:
        if not _person_document_inventory_request(message):
            return None
        return _PERSON_DOCUMENT_INVENTORY_ACTION.search(message)


# Frozen adjacent contracts import this internal recogniser directly.  Runtime
# routing uses the linear helper above; the facade preserves only the historical
# truthy/falsey ``.search`` contract and cannot reintroduce the old lookaheads.
_PERSON_DOCUMENT_INVENTORY = _PersonDocumentInventoryCompatibility()


