def _attachment_count_value(raw: str) -> int | None:
    words = {
        "оба": 2,
        "обе": 2,
        "обоих": 2,
        "обеих": 2,
        "both": 2,
        "two": 2,
        "два": 2,
        "две": 2,
        "двух": 2,
        "двум": 2,
        "три": 3,
        "three": 3,
        "трех": 3,
        "трёх": 3,
        "трем": 3,
        "трём": 3,
        "четыре": 4,
        "four": 4,
        "четырех": 4,
        "четырёх": 4,
        "четырем": 4,
        "четырём": 4,
        "пять": 5,
        "пяти": 5,
        "five": 5,
        "шесть": 6,
        "шести": 6,
        "six": 6,
        "семь": 7,
        "семи": 7,
        "seven": 7,
        "восемь": 8,
        "восьми": 8,
        "eight": 8,
        "девять": 9,
        "девяти": 9,
        "nine": 9,
    }
    folded = str(raw or "").casefold()
    try:
        return int(folded) if folded.isdigit() else words.get(folded)
    except ValueError:  # pragma: no cover - callers constrain the shape
        return None


def _record_source_command_text(message: str) -> str:
    """Authority surface: current speech outside balanced quoted spans.

    Every non-literal file action, source/cardinality selector, restoration cue,
    task kind, scope and terminal owner is proved only here. Quoted spans stay
    on the original message as field, value, search or identity literals after
    an independent unquoted grammar has admitted that use.
    """

    return file_authority_speech(_classification_text(message))


def _current_speech_negates_information_request(message: str) -> bool:
    """True when the current visible clause is an explicit don't-name order.

    Quoted text stays data: the start-anchored gate runs on the unquoted
    current-speech projection.
    """

    return bool(_NEGATED_INFORMATION_REQUEST.search(_record_source_command_text(message)))


def _record_or_source_set_command(message: str) -> bool:
    """True when this surface names a record-set or source-set command."""

    text = _record_source_command_text(message)
    return bool(
        _INTRA_FILE_RECORD_SET_REQUEST.search(text)
        or _LOCAL_BOTH_SOURCE_PAIR.search(text)
        or _multi_attachment_open_task_count(message) is not None
        or _requests_all_attachment_set(message)
        or (_attachment_count_range_side(message) and _MULTI_ATTACHMENT_COMPARISON_COUNT.search(text))
        or _ATTACHMENT_WORD_ORDINAL_PHRASE.search(text)
        or _ATTACHMENT_NUMERIC_ORDINAL.search(text)
        or _ATTACHMENT_SELECTIVE_REFERENCE.search(text)
        or _ATTACHMENT_SEARCH_RESULT_REFERENCE.search(text)
        or _RECENT_UPLOAD_ATTACHMENT_REFERENCE.search(text)
        or _DEICTIC_SAME_FILE_TOPIC.search(text)
        or _DEICTIC_CURRENT_ATTACHMENT_REFERENCE.search(text)
        or _DEICTIC_ATTACHMENT_CONTINUATION.search(text)
        or _ATTACHMENT_LAST_ITEM_REQUEST.search(text)
        or _EXPLICIT_ATTACHMENT_REFERENCE.search(text)
        or _INDIRECT_ATTACHMENT_TOPIC_REFERENCE.search(text)
        or _ATTACHMENT_RECORD_POSITION.search(text)
        or _DOCUMENT_METADATA_OTHER_TARGET.search(text)
        or _ATTACHMENT_ANY_REFERENCE.search(text)
        or _is_document_metadata_request(message)
    )


def _file_route_action_command(message: str) -> bool:
    """True when this surface names a file ACTION, not a mere source pointer."""

    text = _record_source_command_text(message)
    if not text:
        return False
    return bool(
        _ATTACHMENT_LAST_ITEM_REQUEST.search(text)
        or _intra_file_record_set_count(message) is not None
        or _ATTACHMENT_RECORD_POSITION.search(text)
        or _attachment_summary_request(message)
        or _ATTACHMENT_ABSTRACT_REQUEST.search(text)
        or _ATTACHMENT_COMPARISON_REQUEST.search(text)
        or _ATTACHMENT_BODY_LOOKUP_ACTION.search(text)
        or _ATTACHMENT_QUERY_REQUEST.search(text)
        or _is_document_metadata_request(message)
        or office_request_kind(message)
        or office_exact_request_detected(message)
        or _DEICTIC_SAME_FILE_TOPIC.search(text)
        or re.search(
            r"\b(?:прочит\w*|посмотр\w*)\s+"
            r"(?:(?:этот|эту|это|данный|данную|данное|текущий|текущую)\s+)?"
            r"(?:его|е[её]|файл|документ|вложени)\w*\b|"
            r"\b(?:что|кто)\s+там\b|"
            r"^\s*содержим",
            text,
            flags=re.IGNORECASE,
        )
    )


def _independent_source_set_request(message: str) -> bool:
    """Unquoted source-set command that is itself the request, not a pointer."""

    text = _record_source_command_text(message)
    return bool(
        _LOCAL_BOTH_SOURCE_PAIR.search(text)
        or _multi_attachment_open_task_count(message) is not None
        or _requests_all_attachment_set(message)
        or (_attachment_count_range_side(message) and _MULTI_ATTACHMENT_COMPARISON_COUNT.search(text))
        or _ATTACHMENT_WORD_ORDINAL_PHRASE.search(text)
        or _ATTACHMENT_NUMERIC_ORDINAL.search(text)
        or _ATTACHMENT_SELECTIVE_REFERENCE.search(text)
        or _ATTACHMENT_SEARCH_RESULT_REFERENCE.search(text)
        or _RECENT_UPLOAD_ATTACHMENT_REFERENCE.search(text)
        or _DOCUMENT_METADATA_OTHER_TARGET.search(text)
        or _ATTACHMENT_ANY_REFERENCE.search(text)
    )


def _file_operation_in_span(inner: str) -> bool:
    """Quoted inner text is a file action or source/record command."""

    return bool(
        _file_route_action_command(inner)
        or _independent_source_set_request(inner)
        or _record_or_source_set_command(inner)
        or _office_action_present(inner)
    )


def _quoted_record_source_command_is_data(message: str) -> bool:
    """True when the only file operation lives inside balanced quotes.

    A bare unquoted pointer such as ``Этот файл.`` does not authorize an
    action written only inside a quote. An independently actionable
    unquoted request stays live even when its literal target is quoted.
    """

    visible = _classification_text(message)
    quoted_spans = tuple(_QUOTED_TEXT.finditer(visible))
    if not quoted_spans:
        return False
    if _file_route_action_command(message) or _independent_source_set_request(message):
        return False
    return any(
        _file_operation_in_span(span.group(0)[1:-1]) for span in quoted_spans if len(span.group(0)) >= 2
    )


_DOCUMENT_AUTHORED_FILE_COMMAND_PREFIX = re.compile(
    r"^\s*(?:"
    r"(?:в|внутри)\s+(?:(?:этом|данном|процитированном|приложенном|указанном)\s+)?"
    r"(?:файл|документ|вложени|текст)\w*\s+"
    r"(?:(?:написан|сказан|указан|говор)\w*|"
    r"(?:есть|имеется|содержится|приведен\w*|дан\w*)\s+"
    r"(?:просьб|инструкц|команд|требован|указан|фраз)\w*)|"
    r"(?:(?:этот|этот же|данный|процитированный|приложенный)\s+)?"
    r"(?:файл|документ|вложени|текст)\w*\s+"
    r"(?:(?:гласит|говорит|требует|предписывает)|"
    r"(?:содержит|включает)\s+(?:просьб|инструкц|команд|требован|указан|фраз)\w*)|"
    r"(?:the\s+|this\s+|quoted\s+)?(?:file|document|attachment|text)\s+"
    r"(?:says|states|reads)|"
    r"(?:in|inside)\s+(?:the\s+|this\s+|quoted\s+)?"
    r"(?:file|document|attachment|text)\s+(?:it\s+)?(?:says|states|is\s+written)"
    r")\s*[:—–-]\s*",
    re.IGNORECASE,
)
_DOCUMENT_AUTHORED_FILE_COMMAND_SUFFIX = re.compile(
    r"\s*(?:[,;]\s*|[—–-]\s*)"
    r"(?:"
    r"(?:это\s+)?(?:так\s+)?(?:написан|сказан|указан)\w*\s+"
    r"(?:в|внутри)\s+(?:(?:этом|данном|процитированном)\s+)?"
    r"(?:файл|документ|вложени|текст)\w*|"
    r"(?:это\s+)?(?:цитат|фраз|пример)\w*\s+из\s+"
    r"(?:(?:этого|данного|процитированного)\s+)?(?:файл|документ|вложени|текст)\w*|"
    r"(?:as\s+)?(?:written|stated|said)\s+in\s+"
    r"(?:the\s+|this\s+|quoted\s+)?(?:file|document|attachment|text)"
    r")\s*[.!?]*\s*$",
    re.IGNORECASE,
)
_DOCUMENT_AUTHORED_CURRENT_SPEECH_RESET = re.compile(
    r"(?:[.!?;]\s*|\s+[—–-]\s*)"
    r"(?P<request>(?:(?:а|но)\s+)?(?:теперь|сейчас)\b.*|"
    r"(?:мой\s+(?:вопрос|запрос)|я\s+(?:прошу|хочу))\b.*|"
    r"(?:(?:but|and)\s+)?(?:now|my\s+(?:question|request)|i\s+(?:ask|want))\b.*)$",
    re.IGNORECASE,
)


def _document_authored_file_command_is_data(message: str) -> bool:
    """Keep an attributed document command from becoming current authority.

    Telegram's reply metadata identifies bytes but cannot turn prose attributed
    to those bytes into the sender's request.  Balanced quotes are handled by
    :func:`_quoted_record_source_command_is_data`; this closes the equally
    common unquoted ``В документе написано: сделай ...`` form.  A separately
    owned clause after an explicit current-speech reset remains actionable.
    """

    speech = _record_source_command_text(message)
    if not speech:
        return False
    prefix = _DOCUMENT_AUTHORED_FILE_COMMAND_PREFIX.match(speech)
    if prefix is not None:
        reported_payload = speech[prefix.end() :].strip()
        reset = _DOCUMENT_AUTHORED_CURRENT_SPEECH_RESET.search(reported_payload)
        if reset is not None and _file_operation_in_span(reset.group("request")):
            return False
        return _file_operation_in_span(reported_payload)
    suffix = _DOCUMENT_AUTHORED_FILE_COMMAND_SUFFIX.search(speech)
    return bool(suffix is not None and _file_operation_in_span(speech[: suffix.start()]))


_RECORD_SET_NEGATED_ANSWER = "Пункты этого файла по этому запросу называть не буду."
_QUOTED_RECORD_SOURCE_IS_DATA = "Цитата не является текущим запросом к пунктам или файлам."


def _intra_file_record_set_phrase_count(message: str) -> int | None:
    """Closed record-set cardinality, ignoring current-speech negation."""

    # ``Создай ... Включи ровно четыре строки`` describes the body of the new
    # carrier.  Once the bounded direct-file parser proves that output shape,
    # the same number must not be reinterpreted as a selection of four records
    # from the source document.
    if _requested_exact_file_body_count(message) is not None:
        return None
    text = _record_source_command_text(message)
    matched = _INTRA_FILE_RECORD_SET_REQUEST.search(text)
    if matched is None:
        return None
    # ``список из двух пунктов`` describes the requested answer shape; it is
    # not, by itself, a pointer to two records in a private file. Treating the
    # partitive as a deictic record selector made a context-free formatting
    # request require ``files.read`` and replaced the answer with a capability
    # denial. An independently named carrier still owns the file contour
    # (``из файла список из двух пунктов``), while genuine continuations such
    # as ``оба пункта`` and ``две строки этого файла`` retain their semantics.
    prefix = text[: matched.start()]
    self_contained_output_shape = bool(re.search(r"\b(?:спис|ответ)\w*\s+из\s*$", prefix, re.IGNORECASE))
    self_contained_line_shape = bool(
        re.match(
            r"\A\s*(?:(?:пожалуйста|please)\s*[,—-]?\s*)?"
            r"(?:верн|напиш|дай|дайте|подготов|сформир|состав|оформ)\w*\s+"
            r"(?:\d{1,2}|одн\w*|дв\w*|тр[её]\w*|четыр\w*|пят\w*|"
            r"шест\w*|сем\w*|восем\w*|девят\w*)\s+"
            r"(?:(?:коротк|обычн|нейтральн|отдельн|безопасн)\w*\s+){0,4}"
            r"(?:строк|фраз|предложени)\w*\b",
            text,
            re.IGNORECASE,
        )
    )
    independently_names_file = bool(
        _EXPLICIT_ATTACHMENT_REFERENCE.search(text)
        or _DEICTIC_CURRENT_ATTACHMENT_REFERENCE.search(text)
        or _RECENT_UPLOAD_ATTACHMENT_REFERENCE.search(text)
        or _ATTACHMENT_FILENAME_REFERENCE.search(_classification_text(message))
    )
    if (self_contained_output_shape or self_contained_line_shape) and not independently_names_file:
        return None
    return _attachment_count_value(matched.group("count"))


def _intra_file_record_set_count(message: str) -> int | None:
    """Record cardinality inside one selected file, not a file-source count."""

    if _current_speech_negates_information_request(message):
        return None
    return _intra_file_record_set_phrase_count(message)


def _requests_both_attachment_sources(message: str) -> bool:
    """True when any local оба/обе + file-carrier pair exists.

    Each count+noun pair is classified on its own. ``оба пункта`` is a record
    count; ``обоих файлах`` is a source count. An explicit local source pair
    wins and keeps all-or-none multi-file selection active.
    """

    text = _record_source_command_text(message)
    return _LOCAL_BOTH_SOURCE_PAIR.search(text) is not None


def _multi_attachment_summary_count(message: str) -> int | None:
    """Return the explicit bounded set size for a multi-file summary request."""

    text = _record_source_command_text(message)
    if re.search(
        r"\bне\s+(?:(?:надо|нужно|стоит)\s+)?"
        r"(?:обобщ|суммариз|резюмир|перескаж|состав|подготов|сдела|напиш|сформулир)\w*\b",
        text,
        re.IGNORECASE,
    ):
        return None
    if not _attachment_summary_request(message):
        return None
    matched = _MULTI_ATTACHMENT_SUMMARY_COUNT.search(text)
    if matched is None:
        return None
    raw = matched.group("count").casefold()
    return _attachment_count_value(raw)


_MULTI_ATTACHMENT_COMPARISON_COUNT = re.compile(
    r"\b(?P<count>\d{1,2}|оба|обе|обоих|обеих|both|два|две|двух|двум|три|тр[её]х|тр[её]м|"
    r"четыре|четыр[её]х|четыр[её]м|пять|пяти|шесть|шести|семь|семи|восемь|восьми|"
    r"девять|девяти)\s+"
    r"(?:(?:последн|недавн|загруженн|присланн|прикрепл[её]нн|приложенн|эти)\w*\s+){0,3}"
    r"(?:файл|документ|вложен|таблиц|скан)\w*\b",
    re.IGNORECASE,
)
_ALL_ATTACHMENT_SET_REQUEST = re.compile(
    r"(?:"
    r"\bвс(?:е|ё|ех)\s+(?:(?:последн|недавн|загруженн|присланн|прикрепл[её]нн|приложенн|эти)\w*\s+){0,3}"
    r"(?:файл|документ|вложен|таблиц|скан)\w*\b|"
    r"\ball\s+(?:(?:recent|uploaded|attached|these)\s+){0,3}"
    r"(?:files?|documents?|attachments?)\b"
    r")",
    re.IGNORECASE,
)


def _multi_attachment_open_task_count(message: str) -> int | None:
    """Explicit file-set size for a summary, comparison, or both-sources request."""

    summary = _multi_attachment_summary_count(message)
    if summary is not None:
        return summary
    text = _record_source_command_text(message)
    active = _ACTIVE_MULTI_ATTACHMENT_SET.search(text)
    if active is not None:
        active_count = _attachment_count_value(
            str(active.group("count_ru") or active.group("count_en") or "")
        )
        if active_count is not None:
            return active_count
    if _ATTACHMENT_COMPARISON_REQUEST.search(text):
        matched = _MULTI_ATTACHMENT_COMPARISON_COUNT.search(text)
        if matched is not None:
            return _attachment_count_value(matched.group("count"))
    if _requests_both_attachment_sources(message):
        return 2
    return None


_ACTIVE_MULTI_ATTACHMENT_SET = re.compile(
    r"\bэт\w*\s+(?P<count_ru>\d{1,2}|два|две|двух|двум|три|тр[её]х|тр[её]м|"
    r"четыре|четыр[её]х|четыр[её]м|пять|пяти|шесть|шести|семь|семи|восемь|"
    r"восьми|девять|девяти)\s+"
    r"(?:файл|документ|вложен|таблиц|скан)\w*\b|"
    r"\b(?:these|those)\s+(?P<count_en>two|three|four|five|six|seven|eight|nine|\d{1,2})\s+"
    r"(?:files?|documents?|attachments?)\b",
    re.IGNORECASE,
)


def _requests_active_multi_attachment_set(message: str) -> bool:
    """Current conversational file set, distinct from catalog first/last-N."""

    command = _record_source_command_text(message)
    return bool(
        _ACTIVE_MULTI_ATTACHMENT_SET.search(command)
        and not _attachment_count_range_side(message)
        and not _attachment_navigation_filename_mentions(message)
        and not _ATTACHMENT_WORD_ORDINAL_PHRASE.search(command)
        and not _ATTACHMENT_NUMERIC_ORDINAL.search(command)
    )


def _requests_all_attachment_set(message: str) -> bool:
    """Whether current unquoted speech names every file in the active episode."""

    text = _record_source_command_text(message)
    if _ATTACHMENT_ALL_REFERENCE.search(text):
        return True
    return bool(
        _ALL_ATTACHMENT_SET_REQUEST.search(text)
        and (
            _attachment_summary_request(message)
            or _ATTACHMENT_COMPARISON_REQUEST.search(text)
            or _ATTACHMENT_ABSTRACT_REQUEST.search(text)
        )
    )


_ATTACHMENT_COUNT_UNIT = r"(?:од(?:ин|на|но)|дв[ае]|три|четыре|пять|шесть|семь|восемь|девять)"
_ATTACHMENT_COUNT_TENS = r"(?:двадцать|тридцать|сорок|пятьдесят|шестьдесят|семьдесят|восемьдесят|девяносто)"
_ATTACHMENT_COUNT = (
    rf"(?:\d{{1,9}}|{_ATTACHMENT_COUNT_UNIT}|десять|одиннадцать|двенадцать|"
    rf"тринадцать|четырнадцать|пятнадцать|шестнадцать|семнадцать|восемнадцать|"
    rf"девятнадцать|{_ATTACHMENT_COUNT_TENS}(?:\s+{_ATTACHMENT_COUNT_UNIT})?|"
    r"сто|двое|трое|четверо)"
)
_ATTACHMENT_COUNT_NOUN = (
    r"(?:позици|человек|люд|запис|строк|пункт|сотрудник|участник|лиц|им[её]н|"
    r"фамили|элемент|объект|контакт|кандидат|персон|должност|специалист|"
    r"работник|коллег|исполнител|ответственн)"
)
_ATTACHMENT_LIST_NOUN = r"(?:состав|спис|переч|реестр|набор|таблиц|документ|данн|ответ|сводк)"
_ANSWER_CLAIMS_COMPLETE_ATTACHMENT = re.compile(
    rf"(?:"
    # A count in the answer is a whole-document claim even when the question
    # merely asks who is present. Two adjective slots cover natural forms such
    # as «16 отдельных штатных позиций» without treating an ordinal/id as count.
    rf"\b{_ATTACHMENT_COUNT}(?:\s+\w+){{0,2}}\s+{_ATTACHMENT_COUNT_NOUN}\w*\b|"
    # Noun-first summaries require punctuation, so ``Позиция 3 — Иван`` stays
    # an ordinal record reference rather than becoming a whole-file count.
    rf"\b{_ATTACHMENT_COUNT_NOUN}\w*\s*[:—-]\s*{_ATTACHMENT_COUNT}\b|"
    # On incomplete evidence even a bare «только» is safer treated as an
    # exhaustiveness claim than as a verified restriction.
    r"\bтолько\b|"
    r"\bбольше\s+(?:никого|ничего|нет)\b|\b(?:никто|ничто)\s+больше\b|"
    r"\bникого\s+друг\w*\b|\bдруг\w*\s+нет\b|"
    rf"\b(?:больше\s+|друг\w*\s+){_ATTACHMENT_COUNT_NOUN}\w*\s+"
    rf"(?:нет|не\s+(?:указан|найден|обнаружен|упомянут|перечислен|назван|нашл)\w*)\b|"
    rf"\b(?:кроме|помимо)\b[^.!?\n]{{0,80}}\bбольше\b"
    rf"(?:\s+{_ATTACHMENT_COUNT_NOUN}\w*)?\s+"
    rf"(?:нет|не\s+(?:указан|найден|обнаружен|упомянут|перечислен|назван|нашл)\w*)\b|"
    rf"\b(?:полн|исчерпывающ)\w+\s+{_ATTACHMENT_LIST_NOUN}\w*\b|"
    rf"\b{_ATTACHMENT_LIST_NOUN}\w+\s+(?:полн|исчерпывающ)\w*\b|"
    rf"\bединственн\w+\s+{_ATTACHMENT_COUNT_NOUN}\w*\b|"
    rf"\b(?:их\s+|насчитал\w*\s+|наш(?:[её]л|ла|ли)\w*\s+|указан\w*\s+)"
    rf"{_ATTACHMENT_COUNT}\b|"
    r"\b(?:и\s+вс[её]|на\s+этом\s+вс[её])\b|"
    rf"\bитого\s*:?\s*{_ATTACHMENT_COUNT}\b|"
    rf"\b(?:всего|количеств\w*)\s*[:—-]\s*{_ATTACHMENT_COUNT}\b|"
    rf"\bровно\s+{_ATTACHMENT_COUNT}(?:\s+{_ATTACHMENT_COUNT_NOUN}\w*)?\b|"
    r"\b(?:это\s+)?весь\s+(?:спис|состав|переч)\w*\b|"
    r"\bникого\s+не\s+пропустил(?:а|и)?\b|\bостальн\w*\s+нет\b|"
    rf"\bвс[её]\s+{_ATTACHMENT_COUNT}(?:\s+{_ATTACHMENT_COUNT_NOUN}\w*)?\s+"
    r"(?:перечислен|указан|назван)\w*\b|"
    r"\b(?:двое|трое|четверо)\b"
    r")",
    re.IGNORECASE,
)
_ATTACHMENT_REVIEW_NEGATIVE_CLAIM = re.compile(
    r"(?:"
    r"\b(?:ошиб|риск|противореч|нарушен|неточн|проблем|дефект|недоч[её]т|"
    r"замечан|нарекан|уязвим|опечат|расхожден|данн|запис|сведен|упоминан)\w*\b"
    r"[^.!?\n]{0,80}\b(?:нет|отсутств|"
    r"не\s+(?:виж|замет|найд|наш|выяв|обнаруж|указ|упом|содерж)|"
    r"не\s+удал(?:ось|ась|ось)?\s+(?:най|выяв|обнаруж|замет))\w*\b|"
    r"\b(?:нет|отсутств|не\s+(?:виж|замет|найд|наш|выяв|обнаруж|указ|упом|содерж)|"
    r"не\s+удал(?:ось|ась|ось)?\s+(?:най|выяв|обнаруж|замет))\w*\b"
    r"[^.!?\n]{0,80}\b(?:ошиб|риск|противореч|нарушен|неточн|проблем|дефект|"
    r"недоч[её]т|замечан|нарекан|уязвим|опечат|расхожден|данн|запис|сведен|упоминан)\w*\b|"
    r"\bno\s+(?:errors?|risks?|contradictions?|violations?|issues?|problems?|records?|data)\b|"
    r"\b(?:did\s+not|didn't|could\s+not|couldn't)\s+(?:find|detect|identify|notice)\b"
    r"[^.!?\n]{0,60}\b(?:errors?|risks?|contradictions?|violations?|issues?|problems?)\b|"
    r"\b(?:error|risk|issue|problem)[- ]free\b|"
    r"\bwithout\s+(?:any\s+)?(?:errors?|risks?|issues?|problems?)\b|"
    r"\b(?:errors?|risks?|contradictions?|violations?|issues?|problems?|records?|data)\b"
    r"[^.!?\n]{0,60}\b(?:absent|missing|not\s+(?:found|detected|identified|mentioned))\b|"
    r"\b(?:без|никак\w*|ни\s+одн\w*)\b[^.!?\n]{0,40}"
    r"\b(?:ошиб|риск|противореч|нарушен|неточн|проблем|дефект|недоч[её]т|"
    r"замечан|нарекан|уязвим|опечат|расхожден|данн|запис|сведен|упоминан)\w*\b"
    r")",
    re.IGNORECASE,
)
