_CURRENT_DOCUMENT_SECONDARY_ANALYSIS_CUE = re.compile(
    r"\b(?:анализ|проанализ|разбор|оцени|оценк|проверь|ошиб|противореч|риск|"
    r"слабы\w*\s+мест|дума|смысл|суть|посмотр|взглян|analy[sz]|review|critique|"
    r"assess|evaluate|inspect|look\s+over|take\s+a\s+look|walk\s+me\s+through|"
    r"risks?|weakness(?:es)?|what\s+is|think\s+(?:about|of)|make\s+of)\w*\b",
    re.IGNORECASE,
)


def _current_document_secondary_affirmative_surface(command: str) -> str:
    """Remove bounded negative constraints, not positive polite requests."""

    return " ".join(_CURRENT_DOCUMENT_SECONDARY_NEGATIVE_CONSTRAINT.sub(" ", command).split())


def _current_document_secondary_has_closed_extraction(affirmative: str) -> bool:
    """Reject an exact extraction clause while admitting open synthesis outputs."""

    for action in _CURRENT_DOCUMENT_SECONDARY_EXTRACTION_ACTION.finditer(affirmative):
        complement = affirmative[action.end() :]
        boundary = _CURRENT_DOCUMENT_SECONDARY_EXTRACTION_CLAUSE_BOUNDARY.search(complement)
        if boundary is not None:
            complement = complement[: boundary.start()]
        if not _CURRENT_DOCUMENT_SECONDARY_OPEN_EXTRACTION_TARGET.search(complement):
            return True
    return False


def _current_document_secondary_exact_or_metadata_request(message: str, command: str) -> bool:
    """Recognise an exact sibling request without blacklisting useful roots.

    Summary verbs such as ``суммаризируй``, open-output verbs such as
    ``покажи ... тезисы`` and the infinitive ``дать`` share prefixes with
    ``сумма``, ``покажи поле`` and ``дата``. Exact exclusion therefore requires
    either an unambiguous count/metadata form or an extraction action bound to
    an exact target in the same clause.
    """

    affirmative = _current_document_secondary_affirmative_surface(command)
    if _is_document_metadata_request(message) and not _NEGATED_DOCUMENT_METADATA_ACTION.search(command):
        return True
    if (
        _CURRENT_DOCUMENT_SECONDARY_COUNT_REQUEST.search(affirmative)
        or _CURRENT_DOCUMENT_SECONDARY_METADATA_REQUEST.search(affirmative)
        or _CURRENT_DOCUMENT_SECONDARY_EXACT_MODIFIER_TARGET.search(affirmative)
        or _CURRENT_DOCUMENT_SECONDARY_EXACT_FIELD_ACTION.search(affirmative)
        or _CURRENT_DOCUMENT_SECONDARY_EXACT_COMPOSITE_TARGET.search(affirmative)
        or _CURRENT_DOCUMENT_SECONDARY_EXACT_QUOTE_REQUEST.search(affirmative)
        or _current_document_secondary_has_closed_extraction(affirmative)
    ):
        return True
    return bool(
        _CURRENT_DOCUMENT_SECONDARY_EXACT_LOOKUP_ACTION.search(affirmative)
        and _CURRENT_DOCUMENT_SECONDARY_EXACT_MACHINE_TARGET.search(affirmative)
    )


def _current_document_secondary_task_kind(message: str, *, file_count: int) -> str:
    """Return a present, whole-current-document advisory task or ``""``.

    The general attachment classifier deliberately has broad recall because it
    also feeds the primary fallback. Sending private text to the optional model
    needs a stronger contract: a current request, a whole-source task and no
    exact, partial, metadata or effect-bearing sibling clause.
    """

    if file_count < 1:
        return ""
    command = " ".join(_record_source_command_text(message).split())
    affirmative = _current_document_secondary_affirmative_surface(command)
    if (
        not command
        or _attachment_explicitly_partial_scope(message)
        or _CURRENT_DOCUMENT_SECONDARY_PARTIAL_SCOPE.search(command)
        or _CURRENT_DOCUMENT_SECONDARY_SELECTIVE_SCOPE.search(command)
        or _current_document_secondary_exact_or_metadata_request(message, command)
        or _CURRENT_DOCUMENT_SECONDARY_EFFECT.search(affirmative)
        or _CURRENT_DOCUMENT_SECONDARY_NEGATED_REQUEST.search(command)
        or _CURRENT_DOCUMENT_SECONDARY_REPORTED_OR_STATUS.search(command)
        or _document_authored_file_command_is_data(message)
    ):
        return ""

    present_request = bool(
        _CURRENT_DOCUMENT_SECONDARY_RU_IMPERATIVE.search(command)
        or _CURRENT_DOCUMENT_SECONDARY_EN_REQUEST.search(command)
        or _CURRENT_DOCUMENT_SECONDARY_RU_NOUN_REQUEST.fullmatch(command)
        or _CURRENT_DOCUMENT_SECONDARY_EN_NOUN_REQUEST.fullmatch(command)
        or _CURRENT_DOCUMENT_SECONDARY_COMPARISON_QUESTION.fullmatch(command)
        or _noun_first_attachment_review_request(message)
        or (
            _CURRENT_DOCUMENT_SECONDARY_OPEN_QUESTION.search(command)
            and _CURRENT_DOCUMENT_SECONDARY_CURRENT_REFERENCE.search(command)
        )
        or (
            (
                _CURRENT_DOCUMENT_SECONDARY_RU_POLITE.search(command)
                or _CURRENT_DOCUMENT_SECONDARY_EN_POLITE.search(command)
            )
            and _CURRENT_DOCUMENT_SECONDARY_CURRENT_REFERENCE.search(command)
        )
    )
    if not present_request:
        return ""

    classified = _attachment_whole_document_task(message, file_count=file_count)
    if classified in {"summary", "analysis", "comparison"}:
        return classified
    if file_count >= 2 and (
        _ATTACHMENT_COMPARISON_REQUEST.search(command)
        or _CURRENT_DOCUMENT_SECONDARY_COMPARISON_QUESTION.fullmatch(command)
    ):
        return "comparison"
    if _CURRENT_DOCUMENT_SECONDARY_ANALYSIS_CUE.search(command):
        return "analysis"
    if _CURRENT_DOCUMENT_SECONDARY_SUMMARY_CUE.search(command):
        return "summary"
    return ""


def _attachment_query_anchors(message: str, terms: tuple[str, ...]) -> tuple[str, ...]:
    """Return only strong targets which can authorize a closed absence.

    Retrieval may use every cleaned term, but ``NOT_FOUND`` is stronger than a
    useful excerpt: it is allowed only for a quoted/identifier target, a clear
    surname shape, or a proper-name token which is not merely sentence-initial
    capitalization.  Generic request words therefore cannot turn a complete
    scan into a false negative.
    """

    if not terms:
        return ()
    visible = file_turn_authority(message).body_surface()
    anchors: list[str] = []

    def source_qualifier(matched: re.Match[str]) -> bool:
        token = matched.group(0)
        qualifier_prefix = visible[max(0, matched.start() - 24) : matched.start()]
        return bool(
            token.casefold() in _CONTENT_FILE_SUFFIXES
            and re.search(
                r"\b(?:из|в|во|по|для|from|in|for)\s+"
                r"(?:(?:файл|документ|формат|file|document|format)\w*\s+)?\Z",
                qualifier_prefix,
                re.IGNORECASE,
            )
        )

    def admit(candidate: str, *, explicit: bool = False) -> None:
        term = _normalise_attachment_query_term(candidate, explicit=explicit)
        if term in terms and term not in anchors:
            anchors.append(term)

    # A quoted literal or identifier is an explicit target regardless of case.
    for quoted in _ATTACHMENT_QUERY_QUOTED.findall(visible):
        admit(" ".join(quoted.split()), explicit=True)
    for matched in _ATTACHMENT_QUERY_ADDRESS.finditer(visible):
        admit(matched.group(0), explicit=True)
    for matched in _ATTACHMENT_QUERY_TOKEN.finditer(visible):
        token = matched.group(0)
        # ``из ODT`` / ``в PDF`` identifies which already-authorised source a
        # field belongs to; it is not a claim that the letters ODT/PDF occur in
        # the body.  Keep the term useful for ranking if it really occurs, but
        # never let this closed source qualifier prove a body-wide absence.
        # With an explicit quoted field, a bare known extension is far more
        # likely the selected carrier than a second body literal regardless of
        # the surrounding grammar (``из ODT``, ``в документе ODT``, ``ODT
        # документ``). A real format string can still be requested explicitly
        # by quoting it. Machine identifiers such as CASE-404 remain required.
        if source_qualifier(matched) or (anchors and token.casefold() in _CONTENT_FILE_SUFFIXES):
            continue
        if any(char.isdigit() for char in token) or token[1:].isupper():
            admit(token)

    tokens = list(_ATTACHMENT_QUERY_TOKEN.finditer(visible))
    for index, matched in enumerate(tokens):
        if source_qualifier(matched) or (anchors and matched.group(0).casefold() in _CONTENT_FILE_SUFFIXES):
            continue
        token = matched.group(0)
        normalised = _normalise_attachment_query_term(token)
        surname_shaped = bool(
            re.fullmatch(
                r"[а-яё]{4,}(?:ов|ев|ёв|ин|ын|ск|цк|ский|цкий)",
                normalised,
                re.IGNORECASE,
            )
        )
        prefix = visible[: matched.start()]
        sentence_initial = not prefix.strip() or re.search(r"(?:[.!?]|\n)(?:\s+)?\Z", prefix) is not None
        noninitial_proper_name = bool(index > 0 and token[:1].isupper() and not sentence_initial)
        if surname_shaped or noninitial_proper_name:
            admit(token)
    return tuple(anchors[:3])


def _attachment_query_field_prefixes(message: str) -> tuple[str, ...]:
    visible = _classification_text(message)
    found: list[str] = []
    for matched in _ATTACHMENT_QUERY_TOKEN.finditer(visible):
        folded = matched.group(0).casefold()
        prefix = next(
            (candidate for candidate in _ATTACHMENT_QUERY_FIELD_PREFIXES if folded.startswith(candidate)),
            "",
        )
        if prefix and prefix not in found:
            found.append(prefix)
    return tuple(found[:4])


