    r"(?:интернет|сети|веб)\w*\b|"
    r"\b(?:я\s+)?(?:искал|нашл|посмотр|провер)\w*\s+(?:это\s+)?(?:онлайн|online)\b|"
    r"\b(?:(?:был[аои]?|было|были)\s+)?"
    r"(?:бер|взя|получ|найд|основан|собран)\w*\s+(?:с|из|в)\s+"
    r"(?:интернет|сети|веб)\w*\b|"
