def _safe_requested_web_fact_target(value: str) -> str:
    """Validate a domain/address that is answer data rather than provenance."""

    candidate = str(value or "").strip().rstrip(".,;:!?")
    if not candidate:
        return ""
    if candidate.casefold().startswith(("http://", "https://")):
        return candidate if _sanitized_web_url(candidate) else ""
    if candidate.startswith("[") and candidate.endswith("]"):
        probe = f"https://{candidate}/"
    else:
        probe = f"https://{candidate}/"
    return candidate if _sanitized_web_url(probe) else ""


def _requested_web_fact_key(value: str) -> str:
    """Compare host syntax canonically without case-folding path/query data."""

    candidate = _safe_requested_web_fact_target(value)
    if not candidate:
        return ""
    explicit_url = candidate.casefold().startswith(("http://", "https://"))
    probe = candidate if explicit_url else f"https://{candidate}/"
    safe = _sanitized_web_url(probe)
    if not safe:
        return ""
    try:
        parsed = urllib.parse.urlsplit(safe)
        port = parsed.port
        hostname = (parsed.hostname or "").encode("idna").decode("ascii").casefold()
    except (UnicodeError, ValueError):
        return ""
    netloc = f"[{hostname}]" if ":" in hostname else hostname
    if port is not None and not (
        (parsed.scheme.casefold() == "http" and port == 80)
        or (parsed.scheme.casefold() == "https" and port == 443)
    ):
        netloc = f"{netloc}:{port}"

    def normalize_percent_escapes(component: str) -> str:
        return re.sub(
            r"%([0-9A-Fa-f]{2})",
            lambda match: f"%{match.group(1).upper()}",
            component,
        )

    suffix = urllib.parse.urlunsplit(
        (
            parsed.scheme.casefold() if explicit_url else "",
            netloc,
            normalize_percent_escapes(parsed.path),
            normalize_percent_escapes(parsed.query),
            normalize_percent_escapes(parsed.fragment),
        )
    )
    return ("url:" if explicit_url else "bare:") + suffix


def _requested_web_fact_targets(question: str, tool_evidence: Any) -> frozenset[str]:
    """Exact evidence-backed addresses a model may repeat as requested data.

    A source URL and an answer *about* a URL are different authorities.  The
    model never owns citations, but it may need to answer “what is the official
    site/IP?”.  Permit that only for an explicit address question and only when
    the same public token occurs in accepted web evidence.
    """

    if not _ASKS_FOR_WEB_ADDRESS_FACT.search(str(question or "")):
        return frozenset()
    evidence_text = "\n".join(
        str(item.get("output") or "")
        for item in (tool_evidence or [])
        if isinstance(item, Mapping) and str(item.get("tool") or "").startswith("web_")
    )
    if not evidence_text:
        return frozenset()
    targets: set[str] = set()
    for pattern in (_MODEL_PLAIN_WEB_URL, _MODEL_ANY_DOMAIN_OR_IP):
        for match in pattern.finditer(evidence_text):
            safe = _safe_requested_web_fact_target(match.group(0))
            key = _requested_web_fact_key(safe)
            if key:
                targets.add(key)
    return frozenset(targets)


def _attachment_web_literal_key(value: str) -> str:
    """Exact bounded identity for inert attachment data, including private TLDs."""

    candidate = str(value or "").strip().rstrip(".,;:!?")
    if (
        not candidate
        or len(candidate) > 2_048
        or any(char.isspace() for char in candidate)
        or "\\" in candidate
        or "`" in candidate
        or any(unicodedata.category(char).startswith("C") for char in candidate)
    ):
        return ""
    explicit_url = candidate.casefold().startswith(("http://", "https://"))
    authority_start = candidate.find("://") + 3 if explicit_url else 0
    if not explicit_url and candidate.startswith("//"):
        return ""
    boundary = min(
        (
            index
            for index in (
                candidate.find("/", authority_start),
                candidate.find("?", authority_start),
                candidate.find("#", authority_start),
            )
            if index >= 0
        ),
        default=len(candidate),
    )
    authority = candidate[authority_start:boundary]
    suffix = candidate[boundary:]
    if not authority or "@" in authority:
        return ""
    try:
        parsed = urllib.parse.urlsplit(candidate if explicit_url else f"//{candidate}")
        if not parsed.hostname or parsed.username is not None or parsed.password is not None:
            return ""
        # Reading ``port`` is the stdlib's validation boundary (range, syntax).
        _ = parsed.port
        raw_host = parsed.hostname
        host = raw_host.casefold() if ":" in raw_host else raw_host.encode("idna").decode("ascii").casefold()
    except (UnicodeError, ValueError):
        return ""
    if authority.startswith("["):
        close = authority.find("]")
        if close < 0:
            return ""
        port_suffix = authority[close + 1 :]
        normalized_authority = f"[{host}]{port_suffix}"
    else:
        colon = authority.rfind(":")
        port_suffix = authority[colon:] if colon >= 0 else ""
        normalized_authority = f"{host}{port_suffix}"
    prefix = (
        f"{candidate[:authority_start].casefold()}{normalized_authority}"
        if explicit_url
        else normalized_authority
    )
    # Only scheme and host are case-insensitive.  Path/query/fragment and their
    # percent bytes stay exact so a model-mutated case-sensitive endpoint never
    # inherits authority from a nearby literal in the document.
    return ("url:" if explicit_url else "bare:") + prefix + suffix


def _attachment_web_literal_host_key(value: str) -> str:
    """A document URL may answer a narrower question asking for its host."""

    key = _attachment_web_literal_key(value)
    if not key:
        return ""
    kind, canonical = key.split(":", 1)
    if kind == "url":
        parsed = urllib.parse.urlsplit(canonical)
        return f"bare:{parsed.netloc}" if parsed.netloc else ""
    boundary = min(
        (index for index in (canonical.find("/"), canonical.find("?"), canonical.find("#")) if index >= 0),
        default=len(canonical),
    )
    return f"bare:{canonical[:boundary]}" if boundary else ""


def _attachment_web_literal_occurrences(text: str) -> list[tuple[int, int, str]]:
    """Non-overlapping URL/domain candidates, preferring a whole URL."""

    source = str(text or "")
    occurrences: list[tuple[int, int, str]] = []
    occupied: list[tuple[int, int]] = []
    for pattern in (_MODEL_PLAIN_WEB_URL, _MODEL_ANY_DOMAIN_OR_IP):
        for match in pattern.finditer(source):
            start, end = match.span()
            if any(start < old_end and end > old_start for old_start, old_end in occupied):
                continue
            occurrences.append((start, end, match.group(0)))
            occupied.append((start, end))
    return sorted(occurrences, key=lambda item: item[0])


def _attachment_web_fact_targets(attachment_evidence: Any) -> frozenset[str]:
    """Exact URL/domain literals present in the admitted attachment slice."""

    evidence_text = "\n".join(
        str(item.get("output") or "")
        for item in (attachment_evidence or [])
        if isinstance(item, Mapping) and str(item.get("tool") or "") == "attachment"
    )
    targets: set[str] = set()
    for _start, _end, value in _attachment_web_literal_occurrences(evidence_text):
        key = _attachment_web_literal_key(value)
        if key:
            targets.add(key)
            host_key = _attachment_web_literal_host_key(value)
            if host_key:
                targets.add(host_key)
        if len(targets) >= 256:
            break
    return frozenset(targets)


def _reconcile_attachment_web_literals(
    answer: str,
    *,
    allowed: frozenset[str],
) -> tuple[str, bool]:
    """Keep exact document literals inert; remove unsupported web-shaped text."""

    source = str(answer or "")
    original = source.strip()

    # ``источник`` is also the ordinary Russian word for the
    # document the answer is reading.  It is not web provenance by itself.  The
    # previous broad branch entered this reconciler on that word alone and then
    # dropped the whole clause, including an exact value copied from the file.
    # With no web-shaped token there is nothing to reconcile: preserve the
    # model body byte-for-byte and leave the independent no-web claim guards to
    # their own, narrower authority.
    if (
        not _MODEL_MARKDOWN_WEB_LINK.search(source)
        and not _attachment_web_literal_occurrences(source)
        and not _has_explicit_web_provenance_claim(source)
    ):
        return source, False

    def keep(value: str) -> str:
        return value if _attachment_web_literal_key(value) in allowed else ""

    def replace_literals(source: str, *, inert: bool) -> str:
        pieces: list[str] = []
        cursor = 0
        for start, end, value in _attachment_web_literal_occurrences(source):
            pieces.append(source[cursor:start])
            candidate = value.rstrip(".,;:!?")
            suffix = value[len(candidate) :]
            key = _attachment_web_literal_key(candidate)
            if key and key in allowed:
                pieces.append(f"`{candidate}`{suffix}" if inert else f"{candidate}{suffix}")
            else:
                pieces.append(suffix)
            cursor = end
        pieces.append(source[cursor:])
        return "".join(pieces)

    def strip_fabricated_provenance_label(value: str) -> str:
        """Remove only the web-origin claim, retaining the attachment fact."""

        # Do not substitute the broad detection regexes here: their bounded
        # gaps intentionally recognise prose such as ``информация CODE была
        # найдена в интернете`` and therefore include CODE in the match.  This
        # narrower pattern owns only the fabricated origin words.
        rewritten = _ATTACHMENT_FABRICATED_WEB_LABEL.sub(" ", value)
        rewritten = re.sub(
            r"^\s*(?:сообща|утвержда|пиш)\w*\s*[:—-]?\s*",
            "",
            rewritten,
            flags=re.IGNORECASE,
        )
        rewritten = re.sub(r"^[\s:—-]+", "", rewritten)
        rewritten = re.sub(r"[ \t]+([:;,])", r"\1", rewritten)
        rewritten = re.sub(r"[ \t]{2,}", " ", rewritten).strip()
        return f"В документе указано: {rewritten}" if rewritten else ""

    changed = False
    # Strong punctuation, commas and physical lines are independent bounded
    # fragments for provenance purposes.  A URL in one fragment must never
    # grant the broad words ``источник``/``ссылка`` authority over a document
    # fact in its neighbour.
    clauses = re.split(r"(?<=[.!?;,])(?:[ \t]+|\r?\n+)|\r?\n+", original)
    kept: list[str] = []
    for original_clause in clauses:
        clean = original_clause.strip()
        if not clean:
            continue
        # A web literal in one sentence must not give the generic word
        # ``источник`` authority over another sentence.  Reconcile
        # only the clause which actually carried URL/domain/IP syntax.
        if (
            not _MODEL_MARKDOWN_WEB_LINK.search(clean)
            and not _attachment_web_literal_occurrences(clean)
            and not _has_explicit_web_provenance_claim(clean)
        ):
            kept.append(clean)
            continue
        clause_occurrences = _attachment_web_literal_occurrences(clean)
        supported_literal_present = any(
            _attachment_web_literal_key(value.rstrip(".,;:!?")) in allowed
            for _start, _end, value in clause_occurrences
        )
        unsupported_literal_present = any(
            _attachment_web_literal_key(value.rstrip(".,;:!?")) not in allowed
            for _start, _end, value in clause_occurrences
        )
        reconciled_clause = _MODEL_MARKDOWN_WEB_LINK.sub(
            lambda match: keep(str(match.group("url") or "")) or str(match.group("label") or ""),
            clean,
        )
        # Normalize an already model-authored code span before producing our
        # own single safe span.  This also collapses the hostile shape
        # `` `[label](http://private)` `` after the Markdown-link step above.
        reconciled_clause = re.sub(
            r"`([^`\n]{1,2048})`",
            lambda match: (
                str(match.group(1))
                if _attachment_web_literal_key(str(match.group(1))) in allowed
                else str(match.group(0))
            ),
            reconciled_clause,
        )
        reconciled_clause = replace_literals(reconciled_clause, inert=False).strip()
        changed = changed or reconciled_clause != clean
        clean = reconciled_clause
        if not clean:
            continue
        if _claims_current_answer_came_from_the_web(clean):
            # A first-person/current action claim is not a harmless source label.
            # With no URL-shaped carrier, leave it visible for the ordinary
            # no-web hard guard.  Otherwise remove only the fabricated origin
            # phrase: the exact URL and any neighbouring attachment fact stay.
            if supported_literal_present:
                grounded_clause = strip_fabricated_provenance_label(clean)
                changed = True
                if grounded_clause and grounded_clause.casefold() != "в документе указано":
                    kept.append(grounded_clause)
            else:
                kept.append(clean)
            continue
        if _has_explicit_web_provenance_claim(clean) and supported_literal_present:
            grounded_clause = strip_fabricated_provenance_label(clean)
            changed = True
            if grounded_clause and grounded_clause.casefold() != "в документе указано":
                kept.append(grounded_clause)
            continue
        # Removing an unsupported literal may leave only its local label
        # (``неподтверждённая ссылка:``). Drop that bounded fragment, but never
        # a larger clause which also carries an attachment fact.
        if (
            _MODEL_WEB_PROVENANCE_CLAIM.search(clean)
            and unsupported_literal_present
            and _MODEL_WEB_PROVENANCE_FRAGMENT_ONLY.fullmatch(clean)
        ):
            changed = True
            continue
        kept.append(clean)
    reconciled = " ".join(kept).strip()
    inert_text = replace_literals(reconciled, inert=True)
    changed = changed or inert_text != original
    return inert_text, changed


def _attachment_web_literals_are_grounded(answer: str, allowed: frozenset[str]) -> bool:
    if not allowed or _claims_current_answer_came_from_the_web(answer):
        return False
    probe = re.sub(
        r"`([^`\n]{1,2048})`",
        lambda match: (
            match.group(1) if _attachment_web_literal_key(match.group(1)) in allowed else match.group(0)
        ),
        str(answer or ""),
    )
    found = False
    for _start, _end, value in _attachment_web_literal_occurrences(probe):
        found = True
        if _attachment_web_literal_key(value) not in allowed:
            return False
    return found


def _strip_model_authored_web_urls(
    answer: str,
    *,
    requested_fact_targets: frozenset[str] = frozenset(),
    attachment_source_owned: bool = True,
) -> tuple[str, bool]:
    """Remove model-authored provenance, preserving exact requested address facts."""

    original = str(answer or "")
    allowed = set(requested_fact_targets)

    def keep_requested_or_drop(value: str) -> str:
        candidate = _safe_requested_web_fact_target(value)
        key = _requested_web_fact_key(candidate)
        return value if key and key in allowed else ""

    def reconcile_markdown_link(match: re.Match[str]) -> str:
        url = str(match.group("url") or "")
        return url if keep_requested_or_drop(url) else str(match.group("label") or "")

    stripped = _MODEL_MARKDOWN_WEB_LINK.sub(reconcile_markdown_link, original)
    stripped = _MODEL_PLAIN_WEB_URL.sub(
        lambda match: keep_requested_or_drop(match.group(0)),
        stripped,
    )

    def drop_autolink_target(match: re.Match[str]) -> str:
        value = match.group(0)
        if keep_requested_or_drop(value):
            return value
        bare = value.rstrip(".,;:!?")
        suffix = bare.rsplit(".", 1)[-1].casefold() if "." in bare else ""
        # Dotted filenames are content, not provenance.  All other public-looking
        # domains/IPs are model-authored link claims and are removed regardless
        # of TLD; a finite TLD list cannot establish ownership.
        if (
            suffix in _CONTENT_FILE_SUFFIXES
            and "/" not in bare
            and "?" not in bare
            and "#" not in bare
            and not bare.casefold().startswith("www.")
        ):
            return value
        return ""

    stripped = _MODEL_ANY_DOMAIN_OR_IP.sub(drop_autolink_target, stripped)
    lines: list[str] = []
    for line in stripped.splitlines():
        clean = re.sub(r"\(\s*\)", "", line)
        # Removing three model-authored domains from ``(обзоры X, Y и Z)``
        # used to leave the user-visible fragment ``(обзоры, и )``.  The exact
        # source ledger is rendered independently by Telegram; a now-empty
        # generic carrier label has no remaining information and is removed.
        clean = re.sub(
            r"\(\s*(?:обзор\w*|источник\w*|сайт\w*|reviews?|sources?|sites?)"
            r"(?:\s*[,;:/|+-]\s*)*(?:и|and)?\s*\)",
            "",
            clean,
            flags=re.IGNORECASE,
        )
        clean = re.sub(r"\s+(?:[-—–]\s*)+(?=[,.;:!?]|$)", "", clean)
        clean = re.sub(r"\b(?:на|с|at|on|from)\s*(?=[,.;:!?]|$)", "", clean, flags=re.IGNORECASE)
        clean = re.sub(r"[ \t]+([,.;:!?])", r"\1", re.sub(r"[ \t]{2,}", " ", clean)).rstrip()
        if _EMPTY_SOURCE_LABEL.fullmatch(clean) or (
            _model_text_has_external_source(clean) and _MODEL_ANY_DOMAIN_OR_IP.search(clean)
        ):
            continue
        lines.append(clean)
    result = "\n".join(lines).strip()
    if not attachment_source_owned:
        # A public web turn with zero authenticated file evidence must not
        # relabel the web ledger as an attachment.  This was observed verbatim
        # in production: a hardware answer with three web sources concluded
        # that the numbers could not be confirmed "данными из вложения", even
        # though the turn carried no file.  Rewrite only closed provenance
        # carriers; ordinary mentions such as "configuration file" are outside
        # these patterns and remain untouched.
        data_from_attachment = re.compile(
            r"\b(?P<kind>данными|сведениями|информацией)\s+из\s+"
            r"(?:(?:этого|данного|предоставленного|приложенного|прикрепл[её]нного)\s+)?"
            r"(?:вложения|приложенного\s+файла|прикрепл[её]нного\s+файла)\b",
            re.IGNORECASE,
        )

        def data_source(match: re.Match[str]) -> str:
            kind = str(match.group("kind") or "данными")
            return f"{kind} из найденных источников"

        result = data_from_attachment.sub(data_source, result)
        result = re.sub(
            r"\b(?:в|во)\s+(?:(?:этом|данном|предоставленном|приложенном|"
            r"прикрепл[её]нном)\s+)?вложении\b",
            "в найденных источниках",
            result,
            flags=re.IGNORECASE,
        )
        result = re.sub(
            r"\bиз\s+(?:(?:этого|данного|предоставленного|приложенного|"
            r"прикрепл[её]нного)\s+)?вложения\b",
            "из найденных источников",
            result,
            flags=re.IGNORECASE,
        )

        def transferred_file_source(match: re.Match[str]) -> str:
            return (
                "из найденных источников"
                if match.group(0).casefold().startswith("из ")
                else "в найденных источниках"
            )

        result = re.sub(
            r"\b(?:в|из)\s+(?:предоставленн\w*|приложенн\w*|прикрепл[её]нн\w*)\s+"
            r"файл(?:е|а)\b",
            transferred_file_source,
            result,
            flags=re.IGNORECASE,
        )
        result = re.sub(
            r"\b(?P<kind>data|information|details)\s+from\s+(?:the\s+)?"
            r"(?:(?:attached|provided)\s+)?(?:attachment|attached\s+file)\b",
            lambda match: f"{match.group('kind')} from the retrieved sources",
            result,
            flags=re.IGNORECASE,
        )
        result = re.sub(
            r"\b(?P<prep>in|from)\s+(?:the\s+)?(?:attached|provided)\s+"
            r"(?:attachment|file)\b",
            lambda match: (
                "from the retrieved sources"
                if match.group("prep").casefold() == "from"
                else "in the retrieved sources"
            ),
            result,
            flags=re.IGNORECASE,
        )
        result = re.sub(r"[ \t]{2,}", " ", result).strip()
    return result, result != original.strip()


def _project_web_tool_result(
    tool_name: str,
    data: Any,
    *,
    transport_success: bool = True,
    limit: int = 5,
    freshness: str = "",
    source_class: str = "",
    topic_class: str = "",
    expected_query: str = "",
    research_max_sources: int | None = None,
) -> tuple[str, list[dict[str, str]], dict[str, Any] | None]:
    """Classify a web tool result by usable evidence, not handler transport.

    Web handlers deliberately return structured refusal/timeout/empty reports
    instead of raising.  ``ExecutionKernel`` consequently reports transport
    success even though no fact-bearing source arrived.  This projector is the
    single authority used by the prompt, verifier, metadata and delivery.
    """

    try:
        freshness = normalize_search_freshness(freshness)
        source_class = normalize_search_source_class(source_class)
    except ValueError:
        return "failed", [], None
    if not isinstance(topic_class, str):
        return "failed", [], None
    topic_class = topic_class.strip()
    if not transport_success or not isinstance(data, Mapping):
        return "failed", [], None
    if "error" in data and not isinstance(data.get("error"), str):
        return "failed", [], None
    if "query" in data and (
        not isinstance(data.get("query"), str)
        or len(cast(str, data.get("query"))) > MAX_OUTBOUND_WEB_QUERY_CHARS
    ):
        return "failed", [], None
    for class_field in ("source_class", "topic_class"):
        if class_field in data and not isinstance(data.get(class_field), str):
            return "failed", [], None
    for attestation_field in ("source_class_satisfied", "topic_class_satisfied"):
        if attestation_field in data and not isinstance(data.get(attestation_field), bool):
            return "failed", [], None
    if expected_query:
        normalized_expected_query = normalize_outbound_web_query(expected_query)
        if not normalized_expected_query or data.get("query") != normalized_expected_query:
            return "failed", [], None
    if freshness and (
        tool_name not in {"web_search", "web_research"}
        or data.get("freshness") != freshness
        or not search_filter_is_attested(data, "freshness", freshness)
    ):
        # A transport-successful stale/unattested batch is still not evidence
        # for the requested window.  This closes custom-kernel and wrapper seams
        # outside ExecutionKernel's own adapter checks.
        return "failed", [], None
    if "outbound_attempted" not in data:
        return "failed", [], None
    outbound_attempted = data.get("outbound_attempted")
    if not isinstance(outbound_attempted, bool):
        return "failed", [], None
    topic_mismatch_report: dict[str, Any] | None = None
    if (
        tool_name == "web_research"
        and topic_class
        and simple_public_news_topic_mismatch_is_empty(
            data,
            expected_topic_class=topic_class,
            expected_max_sources=(research_max_sources if research_max_sources is not None else 3),
        )
        and data.get("source_class", "") == source_class
        and (
            data.get("source_class_satisfied") is True
            if source_class
            else data.get("source_class_satisfied", False) is False
        )
    ):
        topic_mismatch_report = {
            "query": data.get("query"),
            "outbound_attempted": True,
            "freshness": freshness,
            SEARCH_FILTER_ATTESTATION_KEY: {"freshness": freshness},
            "sources": [],
            "requested_sources": data.get("requested_sources"),
            "completed_sources": data.get("completed_sources"),
            "failed_sources": data.get("failed_sources"),
            "timed_out_sources": data.get("timed_out_sources"),
            "search_timed_out": False,
            "search_failed": True,
            "refused": False,
            "quota_exhausted": False,
            "error": "topic_mismatch",
            "topic_filtered_sources": data.get("topic_filtered_sources"),
            "topic_class": topic_class,
            "topic_class_satisfied": False,
        }
        if source_class:
            topic_mismatch_report["source_class"] = source_class
            topic_mismatch_report["source_class_satisfied"] = True
        if "target_sources" in data:
            topic_mismatch_report["target_sources"] = data.get("target_sources")
    failure_values = [data.get(flag) for flag in _WEB_FAILURE_FLAGS if flag in data]
    malformed_failure_flag = any(not isinstance(value, bool) for value in failure_values)
    hard_failed = (
        malformed_failure_flag
        or any(value is True for value in failure_values)
        or bool(str(data.get("error") or "").strip())
        or bool(
            outbound_attempted is True
            and (
                data.get("refused") is True
                or data.get("quota_exhausted") is True
                or str(data.get("error") or "").strip() == "blocked_url"
            )
        )
    )
    if hard_failed and topic_mismatch_report is None:
        # Contradictory payloads fail closed.  A provider refusal plus a
        # source-looking object is not "partial evidence".
        return "failed", [], None
    if topic_mismatch_report is not None:
        return "empty", [], topic_mismatch_report
    raw_items: list[Any]
    usable: list[dict[str, str]] = []
    usable_payload_items: list[dict[str, Any]] = []
    usable_complete: list[bool] = []
    unusable_count = 0
    incomplete_usable_count = 0
    target_sources: int | None = None

    if tool_name == "web_research":
        if not target_research_report_is_valid(
            data,
            configured_max_sources=research_max_sources,
        ):
            return "failed", [], None
        candidates = data.get("sources")
        raw_items = list(candidates) if isinstance(candidates, list) else []
        report_shape_incomplete = not {
            "requested_sources",
            "completed_sources",
            "timed_out_sources",
            "failed_sources",
            "search_timed_out",
        }.issubset(data)
        if candidates is not None and not isinstance(candidates, list):
            unusable_count += 1
        if len(raw_items) > MAX_RESEARCH_SOURCE_ROWS:
            return "failed", [], None
        for item in raw_items:
            if not isinstance(item, Mapping):
                unusable_count += 1
                continue
            url = _sanitized_web_url(item.get("url"))
            raw_text = item.get("text")
            text = (
                raw_text.strip()
                if isinstance(raw_text, str) and len(raw_text) <= MAX_RESEARCH_SOURCE_TEXT_CHARS
                else ""
            )
            status_code = item.get("status_code")
            item_shape_incomplete = not {
                "text_length",
                "status_code",
                "error",
                "truncated",
            }.issubset(item)
            valid_status = (
                isinstance(status_code, int)
                and not isinstance(status_code, bool)
                and 200 <= status_code < 300
            )
            truncated = item.get("truncated", False)
            valid_truncated = isinstance(truncated, bool)
            text_length = item.get("text_length")
            valid_text_length = (
                isinstance(text_length, int)
                and not isinstance(text_length, bool)
                and text_length >= len(text)
                and text_length <= MAX_RESEARCH_DECLARED_TEXT_CHARS
            )
            valid_error = "error" not in item or isinstance(item.get("error"), str)
            metadata = _bounded_web_research_metadata(item)
            if (
                not url
                or not text
                or len(text) > MAX_RESEARCH_SOURCE_TEXT_CHARS
                or "title" in item
                and not isinstance(item.get("title"), str)
                or str(item.get("error") or "").strip()
                or not valid_status
                or not valid_truncated
                or not valid_text_length
                or not valid_error
                or metadata is None
            ):
                unusable_count += 1
                continue
            usable.append(
                {
                    "url": url,
                    "title": _sanitized_web_title(item.get("title") or item.get("search_title")),
                }
            )
            payload_item: dict[str, Any] = {
                **metadata,
                "url": url,
                "title": usable[-1]["title"],
                "text": text,
                "text_length": text_length,
                "status_code": status_code,
            }
            if "error" in item:
                payload_item["error"] = str(item.get("error") or "")
            if "truncated" in item:
                payload_item["truncated"] = truncated
            usable_payload_items.append(payload_item)
            item_incomplete = bool(
                item_shape_incomplete
                or truncated
                or (isinstance(text_length, int) and text_length > len(text))
            )
            usable_complete.append(not item_incomplete)
            if item_incomplete:
                # The item is fact-bearing but incomplete.  Preserve it as
                # partial evidence; never call the whole research complete.
                incomplete_usable_count += 1
        failed_sources = data.get("failed_sources")
        timed_out_sources = data.get("timed_out_sources")
        completed_sources = data.get("completed_sources")
        requested_sources = data.get("requested_sources")
        raw_target_sources = data.get("target_sources")
        raw_topic_filtered_sources = data.get("topic_filtered_sources")
        count_fields = {
            "failed_sources": failed_sources,
            "timed_out_sources": timed_out_sources,
            "completed_sources": completed_sources,
            "requested_sources": requested_sources,
        }
        count_limits = {
            "failed_sources": MAX_RESEARCH_ATTEMPTS,
            "timed_out_sources": MAX_RESEARCH_ATTEMPTS,
            "completed_sources": MAX_RESEARCH_SOURCE_ROWS,
            "requested_sources": MAX_RESEARCH_ATTEMPTS,
        }
        invalid_counts = any(
            key in data
            and (
                not isinstance(value, int)
                or isinstance(value, bool)
                or value < 0
                or value > count_limits[key]
            )
            for key, value in count_fields.items()
        )
        count_contradiction = bool(
            isinstance(completed_sources, int)
            and completed_sources != len(raw_items)
            or isinstance(requested_sources, int)
            and isinstance(completed_sources, int)
            and isinstance(failed_sources, int)
            and isinstance(timed_out_sources, int)
            and (
                (bool(raw_items) and requested_sources == 0)
                or failed_sources + timed_out_sources > requested_sources
                or requested_sources > completed_sources + failed_sources + timed_out_sources
                or bool(freshness)
                and not research_attempt_counters_are_conserved(data)
            )
        )
        if "target_sources" in data:
            if (
                not isinstance(raw_target_sources, int)
                or isinstance(raw_target_sources, bool)
                or not 0 <= raw_target_sources <= 8
                or report_shape_incomplete
                or not isinstance(requested_sources, int)
                or isinstance(requested_sources, bool)
                or raw_target_sources > requested_sources
                or raw_target_sources == 0
                and (
                    bool(raw_items)
                    or requested_sources != 0
                    or completed_sources != 0
                    or failed_sources != 0
                    or timed_out_sources != 0
                )
            ):
                return "failed", [], None
            target_sources = raw_target_sources
        if invalid_counts or count_contradiction or (target_sources is not None and unusable_count):
            return "failed", [], None
        if "topic_filtered_sources" in data and (
            not isinstance(raw_topic_filtered_sources, int)
            or isinstance(raw_topic_filtered_sources, bool)
            or raw_topic_filtered_sources < 0
            or not isinstance(failed_sources, int)
            or raw_topic_filtered_sources > failed_sources
        ):
            return "failed", [], None
        topic_filtered_sources = (
            raw_topic_filtered_sources if isinstance(raw_topic_filtered_sources, int) else 0
        )
        incomplete = bool(
            report_shape_incomplete
            or (isinstance(failed_sources, int) and failed_sources > 0)
            or (isinstance(timed_out_sources, int) and timed_out_sources > 0)
            or unusable_count
            or incomplete_usable_count
            or topic_filtered_sources
        )
    elif tool_name == "web_search":
        candidates = data.get("results")
        raw_items = list(candidates) if isinstance(candidates, list) else []
        if candidates is not None and not isinstance(candidates, list):
            unusable_count += 1
        if len(raw_items) > _WEB_SEARCH_PROJECTED_ROW_MAX:
            return "failed", [], None
        for item in raw_items:
            if not isinstance(item, Mapping):
                unusable_count += 1
                continue
            url = _sanitized_web_url(item.get("url"))
            raw_fact = item.get("snippet") or item.get("text")
            fact = (
                raw_fact.strip()
                if isinstance(raw_fact, str) and len(raw_fact) <= _WEB_SEARCH_FACT_MAX_CHARS
                else ""
            )
            item_shape_incomplete = not {"title", "snippet", "source"}.issubset(item)
            if (
                not url
                or not fact
                or len(fact) > _WEB_SEARCH_FACT_MAX_CHARS
                or str(item.get("error") or "").strip()
                or ("title" in item and not isinstance(item.get("title"), str))
                or ("source" in item and not isinstance(item.get("source"), str))
            ):
                unusable_count += 1
                continue
            usable.append(
                {
                    "url": url,
                    "title": _sanitized_web_title(item.get("title")),
                }
            )
            usable_payload_items.append(
                {
                    "url": url,
                    "title": usable[-1]["title"],
                    "snippet": fact,
                    "source": str(item.get("source") or "")[:80],
                }
            )
            usable_complete.append(not item_shape_incomplete)
            if item_shape_incomplete:
                unusable_count += 1
        search_count_keys = ("requested_results", "returned_results", "underfilled")
        has_search_counts = any(key in data for key in search_count_keys)
        if has_search_counts:
            # Filtered search is the only production writer of these fields and
            # writes the three as one closed group.  Letting a malformed or
            # contradictory group through would turn a visibly underfilled
            # search into complete evidence.
            if not all(key in data for key in search_count_keys):
                return "failed", [], None
            requested_results = data.get("requested_results")
            returned_results = data.get("returned_results")
            underfilled = data.get("underfilled")
            if (
                not isinstance(requested_results, int)
                or isinstance(requested_results, bool)
                or requested_results < 0
                or not isinstance(returned_results, int)
                or isinstance(returned_results, bool)
                or returned_results < 0
                or returned_results != len(raw_items)
                or returned_results > requested_results
                or requested_results > _WEB_SEARCH_PROJECTED_ROW_MAX
                or not isinstance(underfilled, bool)
                or underfilled != (returned_results < requested_results)
            ):
                return "failed", [], None
        else:
            underfilled = False
        incomplete = bool(unusable_count or underfilled)
    elif tool_name == "web_fetch":
        raw_items = [data]
        fetch_shape_incomplete = not {
            "text_length",
            "status_code",
            "error",
            "truncated",
        }.issubset(data)
        url = _sanitized_web_url(data.get("url"))
        raw_text = data.get("text")
        text = (
            raw_text.strip()
            if isinstance(raw_text, str) and len(raw_text) <= _WEB_FETCH_TEXT_MAX_CHARS
            else ""
        )
        status_code = data.get("status_code")
        valid_status = (
            isinstance(status_code, int) and not isinstance(status_code, bool) and 200 <= status_code < 300
        )
        truncated = data.get("truncated", False)
        valid_truncated = isinstance(truncated, bool)
        text_length = data.get("text_length", len(text))
        valid_text_length = bool(
            isinstance(text_length, int)
            and not isinstance(text_length, bool)
            and text_length >= len(text)
            and text_length <= MAX_RESEARCH_DECLARED_TEXT_CHARS
        )
        valid_error = "error" not in data or isinstance(data.get("error"), str)
        if (
            url
            and text
            and len(text) <= _WEB_FETCH_TEXT_MAX_CHARS
            and not str(data.get("error") or "").strip()
            and valid_status
            and valid_truncated
            and valid_text_length
            and valid_error
            and ("title" not in data or isinstance(data.get("title"), str))
        ):
            usable.append({"url": url, "title": _sanitized_web_title(data.get("title"))})
            usable_payload_items.append(
                {
                    "url": url,
                    "title": usable[-1]["title"],
                    "text": text,
                    "text_length": text_length,
                    "status_code": status_code,
                    "truncated": truncated,
                }
            )
            usable_complete.append(
                not fetch_shape_incomplete
                and not truncated
                and isinstance(text_length, int)
                and text_length == len(text)
            )
            unusable_count = 1 if fetch_shape_incomplete else 0
        else:
            unusable_count = 1
        incomplete = bool(
            usable
            and (
                fetch_shape_incomplete
                or truncated
                or (isinstance(text_length, int) and text_length > len(text))
            )
        )
    else:
        return "failed", [], None

    if source_class and any(not web_source_matches_class(source["url"], source_class) for source in usable):
        # The provider-side filter is an enforcement boundary, not a hint.  A
        # malformed/legacy adapter must not smuggle a Russian fact-bearing page
        # into a foreign-source result merely because its transport succeeded.
        return "failed", [], None

    if tool_name == "web_research" and target_sources is not None:
        complete_identities = {
            identity
            for source, is_complete in zip(usable, usable_complete, strict=True)
            if is_complete and (identity := _canonical_web_url_key(source["url"]))
        }
        target_met = len(complete_identities) >= target_sources
        if target_met:
            if incomplete_usable_count:
                # New target-attested producers must already have discarded
                # replaceable partial rows.  Silently repairing a contradictory
                # report here would detach its attempt counters from its rows.
                return "failed", [], None
            # A filled target is complete even when speculative attempts failed.
            # Partial rows are fallback evidence only and never ride beside a
            # complete accepted target.
            retained = [
                (source, payload)
                for source, payload, is_complete in zip(
                    usable,
                    usable_payload_items,
                    usable_complete,
                    strict=True,
                )
                if is_complete
            ]
            usable = [source for source, _payload in retained]
            usable_payload_items = [payload for _source, payload in retained]
            usable_complete = [True] * len(retained)
            incomplete = bool(topic_filtered_sources)
        else:
            incomplete = True

    all_distinct: list[dict[str, str]] = []
    seen: set[str] = set()
    for source in usable:
        url = source["url"]
        identity = _canonical_web_url_key(url)
        if not identity or identity in seen:
            continue
        seen.add(identity)
        all_distinct.append(source)
    if tool_name == "web_research" and len(all_distinct) < len(usable):
        # Duplicate provider rows shrink the verifier's evidence universe.
        # They remain usable, but cannot authorize a complete publication.
        if target_sources is not None:
            return "failed", [], None
        incomplete = True
    source_limit = max(1, min(int(limit), 10))
    deduplicated = all_distinct[:source_limit]
    if len(all_distinct) > source_limit and (target_sources is None or len(deduplicated) < target_sources):
        # The bounded ledger is also the verifier's evidence universe.  If a
        # distinct readable source is omitted, legacy reports remain partial.
        # A target-attested report is complete once the accepted bounded ledger
        # still carries its whole target; extra direct rows are not a larger
        # promise about the web universe.
        incomplete = True
    if target_sources is not None and len(deduplicated) < target_sources:
        incomplete = True
    if deduplicated:
        if outbound_attempted is False:
            return "failed", [], None
        accepted_urls = {source["url"] for source in deduplicated}
        filtered_items: list[dict[str, Any]] = []
        emitted_urls: set[str] = set()
        for item in usable_payload_items:
            url = str(item.get("url") or "")
            if url not in accepted_urls or url in emitted_urls:
                continue
            emitted_urls.add(url)
            filtered_items.append(item)
        if tool_name == "web_research":
            projected_data = {
                key: data[key]
                for key in (
                    "query",
                    "target_sources",
                    "requested_sources",
                    "completed_sources",
                    "timed_out_sources",
                    "failed_sources",
                    "search_timed_out",
                )
                if key in data
            }
            projected_data["sources"] = filtered_items
            projected_data["usable_sources"] = len(filtered_items)
            if freshness:
                projected_data["freshness"] = freshness
                projected_data[SEARCH_FILTER_ATTESTATION_KEY] = {"freshness": freshness}
            if source_class:
                projected_data["source_class"] = source_class
            projected_data["summary"] = (
                f"Accepted {len(filtered_items)} readable public source"
                f"{'s' if len(filtered_items) != 1 else ''}."
            )
        elif tool_name == "web_search":
            projected_data = {
                "query": str(data.get("query") or "")[:1_000],
                "results": filtered_items,
            }
            if freshness:
                projected_data["freshness"] = freshness
                projected_data[SEARCH_FILTER_ATTESTATION_KEY] = {"freshness": freshness}
        else:
            projected_data = filtered_items[0]
        return ("partial" if incomplete else "sourced"), deduplicated, projected_data
    if outbound_attempted is False:
        # A closed no-results response is meaningful only after an actual
        # provider attempt. `false` plus HTTP-shaped fields is contradictory,
        # not an honest empty internet result.
        return "failed", [], None
    if (
        tool_name == "web_fetch"
        and _sanitized_web_url(data.get("url"))
        and not text
        and not str(data.get("error") or "").strip()
        and valid_status
        and valid_truncated
        and valid_text_length
        and valid_error
        and not fetch_shape_incomplete
    ):
        return "empty", [], None
    if raw_items or unusable_count or incomplete:
        return "failed", [], None
    return "empty", [], None


def _web_source_lines(data: Any, limit: int = 5) -> str:
    """Render only sources proven readable by the shared projector."""

    _, sources, _ = _project_web_tool_result("web_research", data, limit=limit)
    return "\n".join(
        f"- {source['title']}: {source['url']}" if source["title"] else f"- {source['url']}"
        for source in sources
    )


_DIRECT_FILE_WEB_SOURCE = re.compile(
    r"(?:"
    r"\b(?:по\s+(?:данн|информац|материал|результат)\w*|на\s+основе\s+"
    r"(?:данн|информац|материал|результат)\w*)\s+(?:из\s+)?"
    r"(?:интернет\w*|сети|веб\w*|web\b)|"
    r"\b(?:данн|информац|материал|результат)\w*\s+(?:из|в)\s+"
    r"(?:интернет\w*|сети|веб\w*|web\b)|"
    r"\bиз\s+(?:того,?\s+что\s+)?(?:найд\w*|обнаруж\w*|получ\w*)\s+"
    r"(?:в|из)\s+(?:интернет\w*|сети|веб\w*|web\b)|"
    r"\b(?:интернет|веб|web)[-\s]+(?:поиск|источник|данн|информац|материал|результат)\w*"
    r"|\bиз\s+(?:интернет\w*|сети|веб\w*|web\b)"
    r"|\b(?:найд\w*|поищ\w*|возьм\w*|собер\w*|получ\w*)"
    r"[^.!?\n]{0,70}\b(?:в|из)\s+(?:интернет\w*|сети|веб\w*|web\b)"
    # A URL is web authority only when the person names it as an input source.
    # Merely asking to print a company URL in a document must not trigger a
    # fetch or replace an otherwise self-contained file request with research.
    r"|\b(?:на\s+основе|по\s+(?:данн|материал)\w*|из)\s+"
    r"(?:(?:этой|этого|данной|данного)\s+)?"
    r"(?:(?:веб|web)[-\s]*)?(?:страниц|сайт|url|ссылк)\w*"
    r"[^.!?\n]{0,30}https?://[^\s<>()]+"
    r"|\b(?:на\s+основе\s+)?"
    r"(?:данн|информац|материал|результат)\w*\s+"
    r"(?:(?:с|на)\s+)?(?:(?:веб|web)[-\s]*)?"
    r"(?:сайт|портал|страниц)\w*"
    r"|\b(?:по|из|на\s+основе)\s+"
    r"(?:(?:этой|этого|этому|данной|данного|данному)\s+)?"
    r"(?:(?:веб|web)[-\s]*)?(?:сайт|портал|страниц)\w*"
    r"|\b(?:изуч\w*|прочит\w*|проанализ\w*|проверь\w*)\s+"
    r"(?:страниц\w*\s+)?https?://[^\s<>()]+"
    r")",
    re.IGNORECASE,
)
_WEB_FILE_QUERY_FILLER = re.compile(
    r"(?:^|\W)(?:"
    r"сдела\w*|созда\w*|собер\w*|собра\w*|сформир\w*|подготов\w*|оформ\w*|"
    r"состав\w*|выгруз\w*|экспорт\w*|конверт\w*|преобраз\w*|генерир\w*|"
    r"сгенерир\w*|пришл\w*|отправ\w*|сохран\w*|красив\w*|готов\w*|"
    r"word|ворд\w*|docx?|excel|эксел\w*|эксель\w*|xlsx?|pdf|пдф\w*|png|"
    r"таблиц\w*|отч[её]т\w*|справк\w*|документ\w*|файл\w*|книг\w*|поиск\w*"
    r")(?=$|\W)",
    re.IGNORECASE,
)


def _direct_file_request_uses_the_web(message: str) -> bool:
    """An explicit file request names public web material as its source."""

    visible = " ".join(_classification_text(message).split())
    return bool(visible and _is_direct_file_request(visible) and _DIRECT_FILE_WEB_SOURCE.search(visible))


