def _source_token_ranges(words: list[str]) -> list[tuple[int, int, str]]:
    """Return source-noun ranges as ``(start, end, language)`` token offsets."""

    ranges: list[tuple[int, int, str]] = []
    for index, word in enumerate(words):
        if (
            word in _RU_KNOWLEDGE_BASE_HEADS
            and index + 1 < len(words)
            and words[index + 1] in _RU_KNOWLEDGE_BASE_TAILS
        ):
            ranges.append((index, index + 2, "ru"))
        elif word in _RU_SOURCE_WORDS or word in _RU_KNOWLEDGE_BASE_HEADS:
            # A bare «база» is a source head only when the role parser below
            # proves an explicit owner/transfer relation (for example,
            # «в вашей базе»).  Generic «база данных/проекта» has no such role
            # and therefore remains ordinary prose.  Check the two-token
            # «база знаний» form first so its genitive tail is consumed as part
            # of the source NP rather than mistaken for an external owner.
            ranges.append((index, index + 1, "ru"))
        elif word in _EN_SOURCE_WORDS:
            ranges.append((index, index + 1, "en"))
        elif word == "knowledge" and index + 1 < len(words) and words[index + 1] in {"base", "bases"}:
            ranges.append((index, index + 2, "en"))
    return ranges


def _has_structural_personal_source_provenance(message: str) -> bool:
    """Recognise closed personal-source roles before exact-shape transport.

    A source noun is not evidence by itself.  The source NP must contain an
    explicit user owner/relation or a finite transfer marker.  Conversely, an
    explicit non-user ``from/of/by/от`` source wins over an otherwise plausible
    owner or transfer marker.  This keeps generic compounds (``Archive
    reports``), external documents and bare archive rhetoric on the ordinary
    warning path.

    The parser consumes closed token roles and positions, never word suffixes
    or reporting-verb co-occurrence.
    """

    value = str(message or "")
    matches = list(_PROVENANCE_TOKEN_RE.finditer(value))
    words = [match.group(0).casefold() for match in matches]
    if not words:
        return False
    source_ranges = _source_token_ranges(words)

    def _clause_bounds(start: int, end: int) -> tuple[int, int]:
        left_char = max(value.rfind(mark, 0, matches[start].start()) for mark in (".", "!", "?", ";", "\n"))
        right_candidates = [
            found
            for mark in (".", "!", "?", ";", "\n")
            if (found := value.find(mark, matches[end - 1].end())) >= 0
        ]
        right_char = min(right_candidates, default=len(value))
        clause_start = start
        while clause_start > 0 and matches[clause_start - 1].start() > left_char:
            clause_start -= 1
        clause_end = end
        while clause_end < len(matches) and matches[clause_end].start() < right_char:
            clause_end += 1
        return clause_start, clause_end

    def _ru_source_np_is_generic(before: list[str], after: list[str], source_head: str) -> bool:
        if after and after[0] in _RU_GENERIC_SOURCE_HEADS:
            return True
        if (
            source_head in {"данные", "данным", "данными", "данных"}
            and before
            and before[-1] in _RU_CATEGORY_DATA_OWNERS
        ):
            has_owner = any(
                token in _RU_EXPLICIT_SOURCE_OWNERS - _RU_CATEGORY_DATA_OWNERS for token in before[-3:]
            )
            has_transfer = any(token in _RU_SHARED_FULL_SOURCE_WORDS for token in before[-3:])
            has_user_relation = bool(
                len(after) >= 2 and after[0] in {"для", "к", "от", "с"} and after[1] in ru_user_roles
            )
            return not (has_owner or has_transfer or has_user_relation)
        return False

    def _en_source_np_is_generic(before: list[str], after: list[str], source_head: str) -> bool:
        if after and after[0] in _EN_GENERIC_SOURCE_HEADS:
            return True
        if (
            after
            and after[0] in _EN_REPORTING_PREDICATES
            and len(after) >= 2
            and (after[1] in _EN_REPORTING_NOUN_FOLLOWERS or after[1] in _EN_REPORTING_PREDICATES)
        ):
            return True
        if source_head == "data" and before and before[-1] in _EN_CATEGORY_DATA_OWNERS:
            has_owner = any(
                token in _EN_EXPLICIT_SOURCE_OWNERS - _EN_CATEGORY_DATA_OWNERS for token in before[-3:]
            )
            has_transfer = any(_EN_SHARED_SOURCE_RE.fullmatch(token) for token in before[-3:])
            has_user_relation = bool(
                len(after) >= 2
                and after[0] in {"by", "from", "of", "to", "with"}
                and after[1] in _EN_TRANSFER_ACTORS | _EN_EXPLICIT_SOURCE_OWNERS
            )
            return not (has_owner or has_transfer or has_user_relation)
        return False

    ru_user_roles = (
        _RU_EXPLICIT_SOURCE_OWNERS
        | _RU_SOURCE_OWNER_WORDS
        | _RU_TRANSFER_AGENTS
        | _RU_TRANSFER_RECIPIENTS
        | _RU_TRANSFER_ORIGINS
        | _RU_TRANSFER_SUBJECTS
    )
    ru_relation_prepositions = frozenset({"для", "из", "к", "от", "с"})
    ru_transfer_fillers = (
        ru_user_roles
        | _RU_CATEGORY_DATA_OWNERS
        | ru_relation_prepositions
        | frozenset({"был", "была", "были", "было", "вчера", "недавно", "ранее", "сегодня", "уже"})
    )
    en_relation_prepositions = frozenset({"by", "from", "of", "to", "with"})
    en_transfer_fillers = (
        _EN_CATEGORY_DATA_OWNERS
        | _EN_EXPLICIT_SOURCE_OWNERS
        | _EN_TRANSFER_ACTORS
        | _EN_TRANSFER_SUBJECTS
        | en_relation_prepositions
        | frozenset(
            {
                "a",
                "an",
                "been",
                "had",
                "has",
                "have",
                "me",
                "recently",
                "the",
                "today",
                "us",
                "yesterday",
            }
        )
    )

    def _ru_relation_actor_is_user(tokens: list[str], index: int) -> bool:
        if index + 1 >= len(tokens):
            return False
        return tokens[index + 1] in ru_user_roles | _RU_SHARED_SOURCE_WORDS

    def _en_relation_actor_is_user(tokens: list[str], index: int) -> bool:
        actor = tokens[index + 1 :]
        if actor and actor[0] in {"a", "an", "the"}:
            actor = actor[1:]
        return bool(actor and actor[0] in _EN_TRANSFER_ACTORS | _EN_EXPLICIT_SOURCE_OWNERS)

    def _ru_has_external_relation(before: list[str], after: list[str]) -> bool:
        prefix = before[-6:]
        suffix = after[:10]
        for index, token in enumerate(prefix[:-1]):
            if (
                token in ru_relation_prepositions
                and any(
                    item in _RU_SHARED_SOURCE_WORDS | _RU_ACTIVE_TRANSFER_WORDS for item in prefix[:index]
                )
                and not _ru_relation_actor_is_user(prefix, index)
            ):
                return True
        for index, token in enumerate(suffix[:-1]):
            if token in ru_relation_prepositions and not _ru_relation_actor_is_user(suffix, index):
                return True
        relation_boundary = next(
            (
                index
                for index, token in enumerate(after[:5])
                if token
                in _RU_REPORTING_PREDICATES
                | frozenset({"был", "была", "были", "было", "является", "являются"})
            ),
            None,
        )
        if relation_boundary:
            allowed = (
                ru_user_roles
                | ru_relation_prepositions
                | _RU_RELATIVE_WORDS
                | _RU_PASSIVE_COPULAS
                | _RU_SHARED_SOURCE_WORDS
                | _RU_ACTIVE_TRANSFER_WORDS
                | ru_transfer_fillers
            )
            if any(token not in allowed for token in after[:relation_boundary]):
                return True
        for index, token in enumerate(prefix):
            if token in _RU_SHARED_SOURCE_WORDS | _RU_ACTIVE_TRANSFER_WORDS and any(
                following not in ru_transfer_fillers | _RU_SHARED_SOURCE_WORDS
                for following in prefix[index + 1 :]
            ):
                return True
        for index, token in enumerate(suffix):
            if token not in _RU_SHARED_SOURCE_WORDS | _RU_ACTIVE_TRANSFER_WORDS:
                continue
            tail = suffix[index + 1 :]
            boundary = next(
                (
                    offset
                    for offset, following in enumerate(tail)
                    if following in {"и", "но"} | _RU_REPORTING_PREDICATES
                ),
                None,
            )
            if boundary is not None and any(
                following not in ru_transfer_fillers | _RU_SHARED_SOURCE_WORDS
                for following in tail[:boundary]
            ):
                return True
        return False

    def _en_has_external_relation(before: list[str], after: list[str]) -> bool:
        prefix = before[-6:]
        suffix = after[:12]
        for index, token in enumerate(prefix[:-1]):
            if (
                token in en_relation_prepositions
                and any(item in _EN_ACTIVE_TRANSFER_WORDS for item in prefix[:index])
                and not _en_relation_actor_is_user(prefix, index)
            ):
                return True
        for index, token in enumerate(suffix[:-1]):
            if token in en_relation_prepositions and not _en_relation_actor_is_user(suffix, index):
                return True
        relation_boundary = next(
            (
                index
                for index, token in enumerate(after[:5])
                if token in _EN_REPORTING_PREDICATES | _EN_REPORTING_NOUN_FOLLOWERS
            ),
            None,
        )
        if relation_boundary:
            allowed = (
                _EN_EXPLICIT_SOURCE_OWNERS
                | _EN_TRANSFER_ACTORS
                | _EN_TRANSFER_SUBJECTS
                | en_relation_prepositions
                | frozenset({"that", "which", "who"})
                | _EN_PASSIVE_COPULAS
                | frozenset({"been", "had", "has", "have"})
                | _EN_ACTIVE_TRANSFER_WORDS
                | en_transfer_fillers
            )
            if any(token not in allowed for token in after[:relation_boundary]):
                return True
        for index, token in enumerate(prefix):
            if token in _EN_ACTIVE_TRANSFER_WORDS and any(
                following not in en_transfer_fillers | _EN_ACTIVE_TRANSFER_WORDS
                for following in prefix[index + 1 :]
            ):
                return True
        for index, token in enumerate(suffix):
            if token not in _EN_ACTIVE_TRANSFER_WORDS:
                continue
            tail = suffix[index + 1 :]
            boundary = next(
                (
                    offset
                    for offset, following in enumerate(tail)
                    if following in {"and", "but"} | _EN_REPORTING_PREDICATES
                ),
                None,
            )
            if boundary is not None and any(
                following not in en_transfer_fillers | _EN_ACTIVE_TRANSFER_WORDS
                for following in tail[:boundary]
            ):
                return True
        return False

    def _ru_transfer_marked(before: list[str], after: list[str]) -> bool:
        prefix = before[-6:]
        for index, token in enumerate(prefix):
            if token in _RU_SHARED_SOURCE_WORDS | _RU_ACTIVE_TRANSFER_WORDS and all(
                item in ru_transfer_fillers for item in prefix[index + 1 :]
            ):
                return True
        return any(token in _RU_SHARED_SOURCE_WORDS | _RU_ACTIVE_TRANSFER_WORDS for token in after[:10])

    def _en_transfer_marked(before: list[str], after: list[str]) -> bool:
        prefix = before[-6:]
        for token_index, token in enumerate(prefix):
            if token in _EN_ACTIVE_TRANSFER_WORDS and all(
                item in en_transfer_fillers for item in prefix[token_index + 1 :]
            ):
                return True
        structural_prefix = en_transfer_fillers | _EN_PASSIVE_COPULAS | frozenset({"that", "which", "who"})
        for token_index, token in enumerate(after[:12]):
            if token not in _EN_ACTIVE_TRANSFER_WORDS or any(
                item not in structural_prefix for item in after[:token_index]
            ):
                continue
            if any(item in _EN_TRANSFER_SUBJECTS | _EN_PASSIVE_COPULAS for item in after[:token_index]):
                return True
            tail = after[token_index + 1 :]
            if not tail or tail[0] in en_transfer_fillers | _EN_REPORTING_PREDICATES | frozenset(
                {"and", "but"}
            ):
                return True
        return False

    def _ru_direct_role(before: list[str], after: list[str]) -> bool:
        if before and before[-1] in _RU_EXPLICIT_SOURCE_OWNERS:
            return True
        if (
            len(before) >= 2
            and before[-2] in _RU_EXPLICIT_SOURCE_OWNERS
            and before[-1] in _RU_CATEGORY_DATA_OWNERS
        ):
            return True
        if after and after[0] in _RU_SOURCE_OWNER_WORDS:
            return True
        for index, token in enumerate(after[:6]):
            if token in ru_relation_prepositions and _ru_relation_actor_is_user(after, index):
                return True
        return _ru_transfer_marked(before, after)

    def _en_direct_role(before: list[str], after: list[str]) -> bool:
        if before and before[-1] in _EN_EXPLICIT_SOURCE_OWNERS:
            return True
        if (
            len(before) >= 2
            and before[-2] in _EN_EXPLICIT_SOURCE_OWNERS
            and before[-1] in _EN_CATEGORY_DATA_OWNERS
        ):
            return True
        if len(before) >= 2 and before[-2:] in (["user", "s"], ["users", "s"]):
            return True
        if after and after[0] in {"mine", "ours", "yours"}:
            return True
        for index, token in enumerate(after[:8]):
            if token in en_relation_prepositions and _en_relation_actor_is_user(after, index):
                return True
        return _en_transfer_marked(before, after)

    for start, end, language in source_ranges:
        clause_start, clause_end = _clause_bounds(start, end)
        before = words[clause_start:start]
        after = words[end:clause_end]
        if language == "ru":
            if _ru_has_external_relation(before, after) or _ru_source_np_is_generic(
                before, after, words[start]
            ):
                continue
            if _ru_direct_role(before, after):
                return True
        else:
            if _en_has_external_relation(before, after) or _en_source_np_is_generic(
                before, after, words[start]
            ):
                continue
            if _en_direct_role(before, after):
                return True
    return False


def _claims_personal_source_provenance(message: str) -> bool:
    """Whether exact-shape transport would hide a truthful source warning."""

    return _has_structural_personal_source_provenance(message)


#: Ответ САМ говорит, что ничего не нашлось. Предупреждать тут не о чем.
#:
#: Список на ВЫХОДЕ, и это разные условия с списком на входе: промах здесь стоит
#: одного лишнего предупреждения, а не потерянного класса.
_ADMITS_NOTHING_FOUND = re.compile(
    r"не\s+(?:нашл|удалось\s+найти|наход)|нет\s+(?:записей|данных|документ)|"
    r"ничего\s+не\s+нашл|в\s+архиве\s+(?:нет|ничего)|поиск\s+.{0,20}не\s+да[лн]",
    re.IGNORECASE,
)
_ARCHIVE_ABSENCE_CLAUSE_BREAK = re.compile(
    r"[,;]|\b(?:but|however|although|но|однако|зато)\b",
    re.IGNORECASE,
)
_ARCHIVE_ABSENCE_EN_PATTERNS = (
    # A standalone negative answer fragment is already a definitive absence.
    # Exclude bounded comparative/discourse idioms which do not negate a hit.
    re.compile(
        r"^\s*no\b(?!\s+(?:later|earlier|doubt)\b)"
        r"(?!\s+(?:more|less|fewer)\s+than\b)"
        r"[^\n.!?,;]{0,120}[.!?]*\s*$",
        re.IGNORECASE,
    ),
    re.compile(
        r"(?<!\bnot\s)\b(?:none|nothing|nowhere)\b",
        re.IGNORECASE,
    ),
    # Negative quantifier + arbitrary bounded query target + lookup predicate.
    re.compile(
        r"\bno\b(?!\s+(?:later|earlier|doubt)\b)"
        r"(?!\s+(?:more|less|fewer)\s+than\b)[^\n.!?,;]{0,100}\b"
        r"(?:(?:was|were|could\s+be|can\s+be|is|are)\s+)?"
        r"(?:found|located|discovered|retrieved|identified|matched|returned|yielded|"
        r"produced|available|present|surfac\w*|appear\w*|exist\w*)\b|"
        r"\bno\b(?!\s+later\b)[^\n.!?,;]{0,100}\bturned\s+up\b",
        re.IGNORECASE,
    ),
    re.compile(
        r"\bthere\s+(?:is|are|was|were)\s+(?:no|not\s+any)\b"
        r"[^\n.!?,;]{1,100}",
        re.IGNORECASE,
    ),
    re.compile(
        r"\bnone\s+of\b[^\n.!?,;]{0,100}\b"
        r"(?:matched|qualified|fit|was\s+found|were\s+found)\b",
        re.IGNORECASE,
    ),
    re.compile(
        r"\b(?:found|located|discovered|retrieved|identified|returned|yielded|produced)\s+"
        r"(?:absolutely\s+)?(?:no\b[^\n.!?,;]{1,80}|nothing(?:\s+relevant)?\b)|"
        r"(?<!not\s)\b(?:none|nothing)(?:\s+relevant)?\s+"
        r"(?:(?:was|could\s+be)\s+)?"
        r"(?:found|located|discovered|retrieved|identified|returned|yielded|produced|"
        r"surfaced|appeared)\b|"
        r"\bnothing(?:\s+relevant)?\s+(?:turned|came)\s+up\b",
        re.IGNORECASE,
    ),
    # Actor/search failure uses an absence-specific verb but leaves the query target open.
    re.compile(
        r"\b(?:i|we|search|query|lookup)\b[^\n.!?,;]{0,60}\b"
        r"(?:did\s+not|didn't|could\s+not|couldn't|failed\s+to|was\s+unable\s+to)\s+"
        r"(?:find|locate|discover|retrieve|identify|return|yield|produce|match|get)\b",
        re.IGNORECASE,
    ),
    re.compile(
        r"\b(?:i|we|search|query|lookup)\b[^\n.!?,;]{0,60}\b"
        r"(?:has\s+not|hasn't|have\s+not|haven't)\s+"
        r"(?:found|located|discovered|retrieved|identified|returned|matched)\b",
        re.IGNORECASE,
    ),
    re.compile(
        r"\bunable\s+to\s+(?:find|locate|discover|retrieve|identify|return|yield|produce|match)\b",
        re.IGNORECASE,
    ),
    # Arbitrary bounded target in passive/state absence form. Domain predicates
    # such as "not signed" are intentionally outside this closed vocabulary.
    re.compile(
        r"\b[^\n.!?,;]{1,100}\b(?:"
        r"(?:was|were)\s+not|wasn't|weren't|could\s+not\s+be|couldn't\s+be|"
        r"cannot\s+be|can't\s+be)\s+"
        r"(?:found|located|discovered|retrieved|identified|returned)\b",
        re.IGNORECASE,
    ),
    re.compile(
        r"\b[^\n.!?,;]{1,100}\b(?:"
        r"(?:is|are|was|were)\s+(?:(?<!not\s)absent|unavailable|not\s+(?:present|available))|"
        r"isn't\s+(?:present|available)|aren't\s+(?:present|available)|"
        r"wasn't\s+(?:present|available)|weren't\s+(?:present|available))\b",
        re.IGNORECASE,
    ),
    re.compile(
        r"\b[^\n.!?,;]{1,100}\b(?:is|are|was|were)\s+(?<!not\s)missing\b"
        r"(?:\s+(?:from|in)\b[^\n.!?,;]{0,60})?\s*[.!?]*\s*$",
        re.IGNORECASE,
    ),
    re.compile(
        r"\b[^\n.!?,;]{1,100}\b(?:does|do)\s+not\s+exist\b",
        re.IGNORECASE,
    ),
    re.compile(
        r"\b(?:archive|search|query|lookup)\b[^\n.!?,;]{0,60}\b"
        r"(?:contains?\s+no|does\s+not\s+contain|doesn't\s+contain|"
        r"(?<!not\s)lacks?|has\s+(?:no|nothing)|contains?\s+nothing)\b",
        re.IGNORECASE,
    ),
    re.compile(
        r"\b(?:archive|search|query|lookup)\b[^\n.!?,;]{0,60}\b"
        r"(?:is\s+devoid\s+of|drew\s+a\s+blank|came\s+up\s+with\s+nothing)\b",
        re.IGNORECASE,
    ),
    # Zero/empty needs an explicit search/result carrier; unlike lookup
    # predicates, it is not self-scoping.
    re.compile(
        r"\b(?:no(?!\s+(?:more|less|fewer)\s+than\b)|zero|0|"
        r"not\s+(?:a\s+single|one))\s+(?:\w+\s+){0,4}"
        r"(?:results?|hits?|match(?:es)?)\b|"
        r"\bthere\s+(?:was|were)\s+(?:not\s+any|no)\s+"
        r"(?:results?|hits?|match(?:es)?)\b|"
        r"\b(?:search|query|lookup)\b[^\n.!?,;]{0,60}\b"
        r"(?:no|zero|0)\s+(?:\w+\s+){0,4}(?:results?|hits?|match(?:es)?)\b",
        re.IGNORECASE,
    ),
    re.compile(
        r"\b(?:search|query|lookup|archive|results?|hits?|match(?:es)?)\b"
        r"[^\n.!?,;]{0,60}\b(?:(?<!not\s)empty|came\s+(?:back|up)\s+empty|"
        r"(?<!not\s)unsuccessful|yielded\s+nothing|produced\s+nothing)\b|"
        r"\b(?:archive)\b[^\n.!?,;]{0,60}\b"
        r"(?:(?<!not\s)lacks?|does\s+not\s+contain|doesn't\s+contain|has\s+no)\b",
        re.IGNORECASE,
    ),
)
_ARCHIVE_ABSENCE_RU_PATTERNS = (
    re.compile(
        r"(?<!\bне\s)\b(?:ничего|никого|нигде)\b",
        re.IGNORECASE,
    ),
    # Arbitrary bounded target + lookup/availability negative predicate.
    re.compile(
        r"\b[^\n.!?,;]{1,100}\bне\s+(?:"
        r"наш[её]л(?:ся|ась|ось|ись)?|отыскал\w*|найден\w*|обнаружен\w*|выявлен\w*|"
        r"присутствует|имеется|оказал\w*|подош[её]л\w*|встретил\w*|доступ\w*)\b",
        re.IGNORECASE,
    ),
    re.compile(
        r"\b(?:недоступ\w*|не\s+доступ\w*)\b",
        re.IGNORECASE,
    ),
    re.compile(
        r"\b[^\n.!?,;]{1,100}\b(?:найден|обнаружен|выявлен)\w*\s+"
        r"не\s+был\w*\b",
        re.IGNORECASE,
    ),
    re.compile(
        r"\bне\s+(?:найден|обнаружен|выявлен|отыскан|существует)\w*\b"
        r"[^\n.!?,;]{0,100}",
        re.IGNORECASE,
    ),
    re.compile(
        r"\b(?<!не\s)отсутств\w*\b|"
        r"\b(?:архив|поиск|запрос|выдач)\w*[^\n.!?,;]{0,60}\b"
        r"не\s+(?:содерж|име)\w*\b",
        re.IGNORECASE,
    ),
    # Failed lookup in all three natural word orders; target remains bounded,
    # not restricted to a noun allowlist.
    re.compile(
        r"\bне\s+(?:удал\w*|получил\w*|смог\w*)\s+"
        r"(?:найти|отыскать|обнаружить|выявить)[^\n.!?,;]{0,100}",
        re.IGNORECASE,
    ),
    re.compile(
        r"\b(?:найти|отыскать|обнаружить|выявить)[^\n.!?,;]{1,100}\b"
        r"не\s+(?:удал\w*|получил\w*|смог\w*)\b",
        re.IGNORECASE,
    ),
    re.compile(
        r"\b[^\n.!?,;]{1,100}\bне\s+(?:удал\w*|получил\w*|смог\w*)\s+"
        r"(?:найти|отыскать|обнаружить|выявить)\b",
        re.IGNORECASE,
    ),
    re.compile(
        r"\bне\s+(?:нашл\w*|отыскал\w*|обнаружил\w*|выявил\w*|встретил\w*)\b",
        re.IGNORECASE,
    ),
    re.compile(
        r"\bне\s+нашл\w*\s+ни\s+одн\w*\b|"
        r"\bни\s+одн\w*\b|"
        r"\bникак\w*\s+(?:результат|совпадени|документ|файл|материал|данн|запис)\w*\b",
        re.IGNORECASE,
    ),
    # Zero/empty/no-output is meaningful only beside a search/archive/result carrier.
    re.compile(
        r"\b(?:ноль|нет)\s+(?:\w+\s+){0,4}"
        r"(?:результат|совпадени|документ|файл|материал|данн)\w*\b|"
        r"\b(?:результат|совпадени|документ|файл|материал|данн)\w*"
        r"[^\n.!?,;]{0,40}\b(?:нет|не\s+было|не\s+имеется)\b",
        re.IGNORECASE,
    ),
    re.compile(
        r"\bбез\s+(?:результат|совпадени|находок|выдач)\w*\b",
        re.IGNORECASE,
    ),
    re.compile(
        r"\b(?:поиск|запрос|выдач|архив|результат|совпадени)\w*"
        r"[^\n.!?,;]{0,60}\b(?:(?<!не\s)пуст\w*|(?<!не\s)безрезультат\w*|"
        r"(?<!не\s)неуспеш\w*|(?<!не\s)нулев\w*|ноль|нет|"
        r"без\s+(?:результат|совпадени)\w*)\b|"
        r"\b(?:поиск|запрос|выдач)\w*[^\n.!?,;]{0,80}\b"
        r"(?:ничего\s+)?не\s+(?:дал|вернул|выдал|выявил|обнаружил|наш[её]л|прин[её]с)\w*\b",
        re.IGNORECASE,
    ),
    # Bare Russian existential negation is itself an absence predicate.  The
    # clause boundary keeps a later positive result from being swallowed.
    re.compile(r"\bнет\b", re.IGNORECASE),
)


def _archive_definitive_absence_claim(content: str) -> bool:
    """Detect definitive absence anywhere in model-owned archive prose."""

    for sentence in re.split(r"(?<=[.!?])\s+|\n+", content):
        for clause in _ARCHIVE_ABSENCE_CLAUSE_BREAK.split(sentence):
            visible_clause = re.sub(
                r"\[A[1-9]\d*(?:\.[1-9]\d*)?\]",
                " ",
                clause.replace("\u2019", "'").replace("\u2018", "'"),
            ).strip()
            if any(
                pattern.search(visible_clause)
                for pattern in (*_ARCHIVE_ABSENCE_EN_PATTERNS, *_ARCHIVE_ABSENCE_RU_PATTERNS)
            ):
                return True
    return False


_PERSON_EVIDENCE_MISSING = (
    "Не нашла подтверждённых данных по этому вопросу в доступных записях и переписке, "
    "поэтому не буду додумывать подробности."
)


def _grounding_warning(
    content: str,
    answer_grounded: bool | None,
    *,
    about_his_own_papers: bool = False,
    personal_data_reached_the_turn: bool = False,
    asked_about_his_own: bool = False,
    nothing_arrived: bool = False,
    asked_about_the_world: bool = False,
    web_outbound_attempted: bool = False,
    personal_background_offered: bool = False,
) -> str:
    """Предупреждение, которое обязано стоять ПЕРЕД ответом, а не после него.

    Замерено на переписке владельца за 2026-07-30: из 15 ответов ассистента 10 несли
    живые ссылки `[K#]` — забракованных среди них ноль; 5 состояли ТОЛЬКО из пометок
    «(источник вне текущей выборки)» — забракованы все пять (две оценки «минус» и
    реплика «это и предыдущее — неверно, посмотри в штатке»). Корреляция без
    исключений, и она объяснима: такой ответ собран из прежних ходов диалога, чьи
    ссылки при переносе в новый ход стали непроверяемыми, — то есть это пересказ, а
    выглядел он как досье на живого человека с датой рождения и номером личного дела.

    Почему не хватало прежних средств. Пометка честная, но она повторяется по строке
    (в том досье — 14 раз) и от повторения читается как разметка, а не как
    предупреждение. Оговорка `_citation_notice` ставилась ПОСЛЕ тела ответа — под
    1645 знаками её никто не читает — и вдобавок молчала в четырёх случаях из пяти:
    `answer_grounded` там `None`, потому что поиск в тот ход не нашёл НИЧЕГО, и
    ветка «нашлось, но не сослались» не срабатывала.

    Поэтому признак берётся из самого текста: пометки есть, живых ссылок нет — значит
    под ответом нет ни одного источника из текущей выборки, чем бы это ни было
    вызвано. Ответ при этом не отменяется: тот же механизм несёт законные короткие
    продолжения («а его брат?»), и молчать в ответ на них было бы хуже. Меняется
    одно — человек узнаёт об этом до того, как прочтёт факты, а не после.
    """
    body = content or ""
    live = len(_KNOWLEDGE_CITATION_RE.findall(body))
    if live:
        return ""
    if _CITATION_OUT_OF_VIEW in body:
        return (
            "⚠️ Это пересказ прежних ответов этого диалога: в вашем архиве под эти "
            "утверждения сейчас не найдено ни одного источника. Проверьте по документам."
        )
    # Ответ САМ объявил себя взятым из архива, а ссылок в нём нет ни одной.
    #
    # Найдено в живой переписке 2026-08-03: справка о человеке — учёная степень,
    # звание, число научных работ — подана словами «по базе знаний». Ссылок ноль,
    # `answer_grounded` False, и человек ответил «неправильно составила справку».
    # Три из четырёх таких ответов не получили вообще никакого предупреждения:
    # `answer_grounded` там `None`, потому что поиск не нашёл ничего, и обе ветки
    # ниже молчат.
    #
    # Проверять это судьёй не нужно и нечем: судья при пустых данных обязан
    # забраковать всё подряд, и ровно поэтому его в таких ходах не зовут. Зато
    # само утверждение о ПРОИСХОЖДЕНИИ проверяется точно — ссылок ноль, значит из
    # архива не пришло ничего, значит фраза ложна.
    #
    # Стоит после ветки про пересказ: у той свой, более точный текст.
    # Обвинение ставится только там, где личных данных не было ВОВСЕ.
    #
    # Найдено владельцем в живой переписке 2026-08-04. Фраза «это тоже проект из
    # твоей базы» была ПРАВДОЙ: проект приехал полем `user_model`, мимо поиска, —
    # а человек прочёл «сказано, что ответ взят из вашего архива, — это не так».
    # Отсутствие меток `[K#]` доказывает только то, что не сработала ОДНА дорога
    # из трёх; ложной ссылку делает пустота на всех.
    if _CLAIMS_THE_ARCHIVE.search(body) and not personal_data_reached_the_turn:
        return (
            "⚠️ Ниже сказано, что ответ взят из вашего архива, — это не так: под эти "
            "утверждения не найдено ни одной вашей записи. Проверьте факты."
        )
    # Спросили о своём — а не приехало НИЧЕГО, и инструменты не звались.
    #
    # Найдено владельцем 2026-08-04: на вопрос о начале разговора с другим
    # участником пришёл уверенный ответ, в котором первая реплика ЕГО текущей
    # беседы выдана за чужую. Метки того хода: вид «архив», ноль записей, ноль
    # сущностей, ни одного вызова инструмента, уверенность поиска 0.0 — и при
    # этом ни предупреждения, ни судьи.
    #
    # Прежние ветки молчат здесь по построению: `answer_grounded` равен `None`,
    # когда поиск не нашёл ничего, а обвинение в ложной ссылке ставится только по
    # словам ответа. Тут же признак берётся из ФАКТА хода: человек спросил о
    # своих материалах или разговорах, к ответу не пришло ни одной записи, и
    # ответ всё равно длинный и утвердительный.
    #
    # Границы узкие намеренно, потому что предупреждение не по делу обесценивает
    # те, что по делу. Замерено на живых ходах с проставленным видом: сработало
    # бы ровно один раз — на том самом случае. Короткий ответ и честное «не
    # нашлось» пропускаются: там нечего предупреждать.
    # `personal_background_offered` гасит ТОЛЬКО эту ветку, и это не симметрия, а
    # разная цена ошибки. Выведенная модель пользователя — люди, проекты, интересы
    # — на вопрос о СВОЁМ отвечает по существу: владелец уже ловил ложное обвинение,
    # когда ответ сказал «это тоже проект из твоей базы», а проект приехал именно
    # этим полем, мимо поиска. На вопрос же о ВНЕШНЕМ мире («в каком году X был
    # президентом») сводка о коллегах не отвечает ничем — и там она молчать не должна.
    if (
        asked_about_his_own
        and nothing_arrived
        and not personal_background_offered
        and len(body) >= 200
        and not _ADMITS_NOTHING_FOUND.search(body)
    ):
        return (
            "⚠️ По этому вопросу не нашлось ни одной вашей записи, и инструменты не "
            "вызывались — ответ ниже построен на памяти разговора, а она хранит только "
            "последние ходы. Проверьте факты."
        )
    # То же самое, но про ВНЕШНИЙ мир: спросили о нём — в интернет не ходили.
    #
    # Найдено в живой переписке владельца 2026-08-04. «Где в Донецке в наличии
    # есть RPI5?» → «давай» → ответ: магазин «IT-Store», статус «В НАЛИЧИИ», цена
    # 2 800–3 200 грн, и всё это под словами «Вот что удалось найти». Метки того
    # хода: `tools_used` пуст, `verification: skipped`, предупреждения ноль.
    # Наличие товара в магазине и его цена — не мнение и не общее знание: их
    # либо смотрят, либо выдумывают.
    #
    # Ветка симметрична соседней и такая же узкая. Она НЕ повторяет пометку «не
    # опирается на вашу базу», которую владелец дважды просил убрать: та
    # появлялась под каждым ответом о внешнем мире и потому обесценилась. Здесь
    # условие другое — вид «интернет» поставил арбитр, то есть вопрос сам требовал
    # свежих сведений, а не пришло ничего.
    if (
        asked_about_the_world
        and nothing_arrived
        and len(body) >= 200
        and not _ADMITS_NOTHING_FOUND.search(body)
    ):
        if web_outbound_attempted:
            return (
                "⚠️ Веб-запрос был отправлен, но пригодных источников по нему не получено. "
                "Факты ниже не подтверждены интернет-источником; проверьте их отдельно."
            )
        return (
            "⚠️ В интернет по этому вопросу не ходили: ни одна страница не читалась. "
            "Всё ниже — по памяти модели, а она устаревает и не знает наличия, цен и "
            "адресов на сегодня. Проверьте у источника."
        )
    if answer_grounded is False:
        if not about_his_own_papers:
            # Пометка осталась ровно для одного случая: человек спросил о СВОИХ
            # данных, архив ответил УВЕРЕННО, а модель его не использовала — то
            # есть сочинила про документы, лежащие перед ней.
            #
            # Владелец просил убрать её дважды, и он прав. Она появлялась под
            # каждым ответом о внешнем мире («ответ про курс доллара не опирается
            # на вашу базу» — своей записи о курсе у него и нет), под смешанными
            # ответами и под случайными слабыми совпадениями. Предупреждение,
            # которое всегда некстати, обесценивает те, что по делу: их
            # перестают читать.
            return ""
        return (
            "⚠️ Ответ не опирается ни на одну запись вашей базы, хотя записи по запросу "
            "нашлись — проверьте ключевые факты."
        )
    return ""


def _citation_sort_key(label: str) -> tuple[int, int]:
    """Order K-labelled citations numerically; unlabelled (tool) sources come last."""
    if label[:1].upper() == "K" and label[1:].isdigit():
        return (0, int(label[1:]))
    return (1, 0)


def _citation_date(source: dict[str, Any] | None) -> str:
    """Дата, которую честно показать рядом с источником.

    Своя дата документа, если она известна из провенанса файла; иначе дата записи.
    Порядок именно такой: у импортированного разом корпуса `updated_at` одинаков у
    всего архива и о документе не говорит ничего, а собственную дату записал
    редактор при сохранении.
    """
    if not source:
        return ""
    metadata = source.get("metadata_json")
    if isinstance(metadata, str):
        try:
            metadata = json.loads(metadata)
        except (TypeError, ValueError):
            metadata = None
    if isinstance(metadata, dict):
        own = str(metadata.get("document_date") or "").strip()[:10]
        if len(own) == 10:
            return own
    return str(source.get("updated_at") or "")[:10]


def _citation_notice(
    citations: list[dict[str, str]], answer_grounded: bool | None, *, inferred: bool = False
) -> str:
    """User-facing source legend, or an honest note when a personal answer is ungrounded.

    `inferred=True` — атрибуция не из метки модели, а из догадки: запись была
    единственным сильным попаданием, и мы предположили, что ответ на ней. Подписать
    это «Источники» значило бы утверждать то, чего никто не проверял, поэтому
    формулировка другая. Отличие важно не косметически: та же атрибуция кормит
    feedback и lifecycle, и человек, увидев «Источники», не станет перепроверять.
    """
    labelled = []
    for item in citations:
        if not item.get("title"):
            continue
        # Дата — часть ответа на вопрос «откуда это». Без неё человек не отличит
        # позапрошлогоднюю редакцию от вчерашней и вынужден открывать запись, чтобы
        # понять, стоит ли ей верить. Своя дата документа предпочтительнее даты
        # записи: вторая у импортированного корпуса одна на весь архив.
        text = f"[{item['label']}] {item['title']}" if item["label"] else str(item["title"])
        if item.get("date"):
            text += f" ({item['date']})"
        labelled.append(text)
    if labelled and inferred:
        return "📎 Вероятно, на основе: " + "; ".join(labelled) + " (модель не сослалась явно)"
    if labelled:
        return "📎 Источники: " + "; ".join(labelled)
    # Случай «нашлось, но не сослались» переехал в `_grounding_warning`: это
    # предупреждение, а не легенда, и место ему ПЕРЕД ответом. Здесь остаётся только
    # легенда источников — иначе одно и то же говорилось бы дважды, сверху и снизу.
    return ""


